import React, { useState, useEffect, useRef } from 'react';
import type { RPGNexusPanelProps, RPGGameState, RPGGameLocation, RPGDynamicAction, RPGSceneData, MarketItem } from '../../types';
import { AgentName, ArtifactType, ArtifactRarity } from '../../types';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { globalSoundEngine } from '../../lib/SoundEngine';
import { QuestCinemaEngine } from '../../lib/video/QuestCinemaEngine';

// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    // Helper to extract JSON object if surrounded by text
    const firstBrace = cleanText.indexOf('{');
    const lastBrace = cleanText.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
        cleanText = cleanText.substring(firstBrace, lastBrace + 1);
    }
    return JSON.parse(cleanText) as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

interface RPGScanResultLocation {
  description: string;
  color?: string;
  risk?: string;
  icon?: string;
}

const FALLBACK_LOCATIONS: Record<string, RPGScanResultLocation> = {
  "The Void Edge": { description: "A precipice where reality dissolves into static.", color: "text-slate-400", risk: "Extreme", icon: "ri-mist-line" },
  "Crystal Spire": { description: "A tower of singing glass reaching into the Aethel.", color: "text-cyan-300", risk: "Low", icon: "ri-building-2-line" },
  "Axiom Forge": { description: "Industrial complex where truths are hammered into shape.", color: "text-amber-400", risk: "Medium", icon: "ri-hammer-line" }
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Scan for Anomalies', type: 'ritual', risk: 0.2, isDynamic: false },
    { id: 'def_rest', label: 'Recalibrate Systems', type: 'talk', risk: 0, isDynamic: false }
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const logContainerRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null,
    sceneHistory: [] 
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");

  // -- Video & Cinema State --
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isCompilingStory, setIsCompilingStory] = useState(false);
  const [compilationProgress, setCompilationProgress] = useState(0);

  // -- Audio / Narrator State --
  const [isNarratorEnabled, setIsNarratorEnabled] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [currentlyPlayingText, setCurrentlyPlayingText] = useState<string | null>(null);

  // -- Loot State --
  const [foundLoot, setFoundLoot] = useState<MarketItem | null>(null);

  // -- Refs --
  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
        if (audioContextRef.current) audioContextRef.current.close();
    }
  }, []);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  // -- Auto-scroll without page jumping --
  useEffect(() => {
    if (logContainerRef.current) {
        logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
    }
  }, [gameState.narrativeHistory]); 

  const getRiskColor = (risk: number) => {
      if (risk >= 0.7) return 'border-rose-500 hover:bg-rose-900/30 text-rose-200';
      if (risk >= 0.4) return 'border-amber-500 hover:bg-amber-900/30 text-amber-200';
      return 'border-emerald-500 hover:bg-emerald-900/30 text-emerald-200';
  };

  // --- AUDIO HELPER ---
  const playNarrativeAudio = async (text: string) => {
    if (!text) return;
    setIsPlayingAudio(true);
    setCurrentlyPlayingText(text);

    try {
        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        }
        if (audioContextRef.current.state === 'suspended') {
            await audioContextRef.current.resume();
        }

        const audioData = await generateSpeech(text);
        if (audioData) {
            const buffer = await audioContextRef.current.decodeAudioData(audioData);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => {
                setIsPlayingAudio(false);
                setCurrentlyPlayingText(null);
            };
            source.start(0);
        } else {
             // Fallback
             const utterance = new SpeechSynthesisUtterance(text);
             utterance.onend = () => {
                 setIsPlayingAudio(false);
                 setCurrentlyPlayingText(null);
             };
             window.speechSynthesis.speak(utterance);
        }
    } catch (e) {
        console.error("Audio playback error", e);
        setIsPlayingAudio(false);
        setCurrentlyPlayingText(null);
    }
  };


  // --- CORE ENGINE ---

  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    globalSoundEngine.playSFX('click');
    addEchoMessage(AgentName.RPGNexusAgent, "Scanning sector for stability variances...", "text-indigo-300");

    const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting with entropy level ${currentEntropy.toFixed(2)}.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1 sentence)
    - "color": string (Tailwind text class, e.g. "text-red-400")
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class, e.g. "ri-skull-line")`;

    try {
      const response = await invokeGemini(prompt, "You are a JSON generator. Do not include markdown formatting.");
      const locations = cleanAndParseJSON<Record<string, RPGScanResultLocation>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);

      if (isNarratorEnabled) playNarrativeAudio("Sector scan complete. Anomalies detected.");
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: RPGScanResultLocation) => {
    setScanResults(null); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); // Reset video on travel
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const textPrompt = `You are the Game Master. The player has just arrived at "${locationName}" (${locationData.description}).
      Current Entropy: ${currentEntropy}.
      1. Write a vivid, 2-sentence sensory description of the scene.
      2. Provide 3 distinct actions the player can take (Explore, Talk, Analyze, Ritual, etc.).
      3. Create a short quest title related to this location.

      Return JSON:
      {
        "description": "...",
        "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
        "quest": { "title": "...", "description": "...", "rewards": { "xp": 100, "flux": 50 } }
      }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        // Image Gen
        const imagePrompt = `Sci-fi fantasy concept art, ${locationName}, ${textData.description}, cinematic lighting, atmospheric, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;
        generateImage(imagePrompt).then(url => {
          if (url) {
            setGameState(prev => {
                const newHistoryEntry: RPGSceneData = {
                    imageUrl: url,
                    location: locationName as RPGGameLocation,
                    description: textData.description,
                    timestamp: Date.now()
                };
                return { 
                    ...prev, 
                    currentSceneImageUrl: url,
                    sceneHistory: [...(prev.sceneHistory || []), newHistoryEntry] 
                };
            });
          }
        });

        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions || DEFAULT_ACTIONS,
          activeQuests: prev.activeQuests.length < 3 ? [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }] : prev.activeQuests,
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));

        if (isNarratorEnabled) playNarrativeAudio(textData.description);
      }
    } catch (e) {
      console.error("Travel generation failed", e);
      addEchoMessage(AgentName.System, "Navigational data corrupted. Using fallback protocols.", "text-rose-400");
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); 
    setFoundLoot(null); // Reset loot view
    globalSoundEngine.playSFX('click');

    setGameState(prev => ({
        ...prev,
        narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${actionLabel}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})
    Current Scene: ${gameState.currentSceneDescription}

    Determine the outcome. 
    1. Write a 1-2 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. PROVIDE 3 NEW Available Actions for the player based on the new situation.
    4. Decide if a loot item (Card) is found (20% chance). If yes, provide "lootItem" details.

    Return JSON:
    {
      "resultText": "...",
      "deltaIntegrity": -5, 
      "deltaSanity": 0,
      "deltaFlux": 10,
      "newActions": [ { "id": "new_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
      "lootItem": { "name": "...", "rarity": "Common|Rare|Legendary", "type": "Relic", "description": "..." } (OPTIONAL)
    }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only. Do not wrap in markdown.");
        const outcome = cleanAndParseJSON<any>(response);

        if (outcome) {
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));

            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: (outcome.newActions && outcome.newActions.length > 0) ? outcome.newActions : DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));

            if (outcome.deltaFlux && onUpdateProfile && activeProfile) {
                onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + outcome.deltaFlux });
                addEchoMessage(AgentName.RPGNexusAgent, `Flux ${outcome.deltaFlux > 0 ? '+' : ''}${outcome.deltaFlux}`, outcome.deltaFlux > 0 ? 'text-amber-300' : 'text-rose-400');
            }

            // Handle Loot Generation (don't add to inventory yet)
            if (outcome.lootItem) {
                const newItem: MarketItem = {
                    id: `loot-${Date.now()}`,
                    name: outcome.lootItem.name,
                    type: outcome.lootItem.type || 'Relic',
                    rarity: outcome.lootItem.rarity || ArtifactRarity.Common,
                    description: outcome.lootItem.description || "An interesting find.",
                    visualPromptMod: "artifact",
                    cost: 100, // Nominal value
                    icon: 'ri-treasure-map-line'
                };
                setFoundLoot(newItem);
                // NOT adding to profile inventory here anymore, waiting for user confirmation via UI

                addEchoMessage(AgentName.RPGNexusAgent, `Loot Discovered: ${newItem.name}. Examine to acquire.`, 'text-cyan-300');

                // Optionally generate visual memory artifact of the discovery event itself
                if (onArtifactCreated) {
                     onArtifactCreated({
                        id: newItem.id,
                        name: newItem.name,
                        type: ArtifactType.RitualResidue,
                        rarity: newItem.rarity,
                        description: newItem.description,
                        timestamp: Date.now()
                    });
                }
                globalSoundEngine.playSFX('success');
            }

            if (risk > 0.5) onUpdateSystemMetrics(0.01, -0.01); 
            if (isNarratorEnabled) playNarrativeAudio(outcome.resultText);

        } else {
             setGameState(prev => ({
                ...prev,
                availableActions: DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: "The ether churns, obscuring the outcome. (Data corruption)", type: 'system', timestamp: Date.now() }]
            }));
        }
    } catch (e) {
        addEchoMessage(AgentName.System, "Action resolution failed. Systems rebooting...", "text-rose-400");
        setGameState(prev => ({ ...prev, availableActions: DEFAULT_ACTIONS }));
    } finally {
        setIsProcessingTurn(false);
    }
  };

  // --- NEW FEATURES ---

  const handleGenerateSceneVideo = async () => {
      if (isAnimatingScene || !gameState.currentSceneImageUrl) return;
      setIsAnimatingScene(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Animating scene via Veo-3.1...", "text-fuchsia-300");

      try {
          const prompt = `Cinematic subtle motion, atmospheric video of ${gameState.currentSceneDescription}. ${currentEntropy > 0.6 ? 'Glitch art style, disturbing movement.' : 'Serene, flowing motion.'}`;
          const videoUrl = await generateVideo(prompt, gameState.currentSceneImageUrl);
          if (videoUrl) {
              setCurrentSceneVideoUrl(videoUrl);
              addEchoMessage(AgentName.RPGNexusAgent, "Scene animation compiled.", "text-emerald-300");
          } else {
              throw new Error("No video URL returned.");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Video generation failed.", "text-rose-400");
      } finally {
          setIsAnimatingScene(false);
      }
  };

  const handleCompileStoryVideo = async () => {
      if (isCompilingStory || !gameState.sceneHistory || gameState.sceneHistory.length === 0) {
          addEchoMessage(AgentName.System, "No scene history to compile.", "text-yellow-400");
          return;
      }

      setIsCompilingStory(true);
      setCompilationProgress(0);
      addEchoMessage(AgentName.RPGNexusAgent, "Compiling narrative history into Quest Cinema...", "text-amber-300");

      try {
          if (!cinemaEngineRef.current) {
              cinemaEngineRef.current = new QuestCinemaEngine();
          }

          const slides = gameState.sceneHistory.map(scene => ({
              imageUrl: scene.imageUrl,
              text: scene.description
          }));

          const blob = await cinemaEngineRef.current.compileVideo(
              slides,
              (progress) => setCompilationProgress(Math.round(progress * 100)),
              async (text) => await generateSpeech(text) 
          );

          if (blob) {
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `Nexus_Story_${Date.now()}.webm`; 
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              addEchoMessage(AgentName.RPGNexusAgent, "Story Compilation Complete. Downloading...", "text-emerald-300");

              if (onArtifactCreated) {
                  onArtifactCreated({
                      id: `cinema-${Date.now()}`,
                      name: "Quest Cinema Log",
                      type: ArtifactType.VisualMemory,
                      rarity: ArtifactRarity.Rare,
                      description: "A compiled video log of your recent journey.",
                      imageUrl: gameState.currentSceneImageUrl || "", // Thumbnail
                      timestamp: Date.now()
                  });
              }
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Story compilation failed.", "text-rose-400");
      } finally {
          setIsCompilingStory(false);
          setCompilationProgress(0);
      }
  };

  const handleDownloadStory = () => {
      const storyText = gameState.narrativeHistory.map(n => `[${new Date(n.timestamp).toLocaleTimeString()}] ${n.type.toUpperCase()}: ${n.text}`).join('\n\n');
      const blob = new Blob([storyText], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Nexus_Log_${Date.now()}.txt`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      addEchoMessage(AgentName.RPGNexusAgent, "Narrative log exported.", "text-cyan-300");
  };

  const handleReimagineScene = async () => {
      if (isProcessingTurn || !gameState.currentSceneDescription) return;
      setIsProcessingTurn(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Re-imagining reality matrix...", "text-purple-300");

      try {
          const imagePrompt = `Sci-fi fantasy concept art, ${gameState.currentLocation}, ${gameState.currentSceneDescription}, cinematic lighting, atmospheric, ${activeProfile?.visualFilter || 'cyberpunk'} style, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;

          const url = await generateImage(imagePrompt);
          if (url) {
             setGameState(prev => ({ 
                  ...prev, 
                  currentSceneImageUrl: url,
                  sceneHistory: [...(prev.sceneHistory || []), {
                      imageUrl: url,
                      location: prev.currentLocation,
                      description: prev.currentSceneDescription || "Reimagined scene",
                      timestamp: Date.now()
                  }]
              }));
              setCurrentSceneVideoUrl(null); // Clear video if scene changes
              addEchoMessage(AgentName.RPGNexusAgent, "Visuals re-synthesized.", "text-emerald-300");
          }
      } catch (e) {
          addEchoMessage(AgentName.System, "Reimagine failed.", "text-rose-400");
      } finally {
          setIsProcessingTurn(false);
      }
  };

  const handleAddToInventory = () => {
      if (activeProfile && foundLoot) {
          onUpdateProfile({ ...activeProfile, inventory: [...activeProfile.inventory, foundLoot] });
          addEchoMessage(AgentName.RPGNexusAgent, `Added ${foundLoot.name} to inventory.`, "text-emerald-400");
      }
      setFoundLoot(null);
  };


  // -- Renders --

  const renderInitialization = () => (
    <div className="flex flex-col items-center justify-center h-full p-6 animate-fade-in-up bg-slate-900/50 text-center">
      <div className="text-5xl text-indigo-500 mb-6 animate-pulse"><i className="ri-radar-line"></i></div>
      <h3 className="text-2xl font-cinzel text-indigo-300 mb-3">Campaign Initialization</h3>
      <p className="text-base text-slate-400 mb-8 max-w-lg leading-relaxed">
        The Nexus Engine requires an insertion vector. Scan the local entropy field to materialize potential timelines.
      </p>

      {scanResults ? (
         <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl">
            {Object.entries(scanResults).map(([name, dataRaw]) => {
                const data = dataRaw as RPGScanResultLocation;
                return (
                    <button 
                        key={name}
                        onClick={() => handleTravel(name, data)}
                        className="flex flex-col p-6 bg-slate-800/80 border-2 border-slate-600 rounded-xl hover:bg-slate-700 hover:border-cyan-500 hover:shadow-2xl hover:shadow-cyan-500/20 transition-all group text-left transform hover:-translate-y-1"
                    >
                        <div className="flex items-center justify-between mb-4 w-full">
                            <i className={`${data.icon || 'ri-map-pin-line'} text-3xl ${data.color || 'text-slate-200'}`}></i>
                            <span className="text-xs uppercase font-bold tracking-wider bg-slate-900 px-3 py-1 rounded text-slate-400 group-hover:text-white transition-colors">{data.risk} Risk</span>
                        </div>
                        <h4 className="font-cinzel font-bold text-xl text-slate-200 group-hover:text-cyan-300 mb-2">{name}</h4>
                        <p className="text-sm text-slate-400 font-cormorant leading-relaxed">{data.description}</p>
                    </button>
                );
            })}
         </div>
      ) : (
        <Button onClick={handleScanSector} disabled={isScanning} className="px-10 py-4 text-base tracking-widest bg-indigo-600 hover:bg-indigo-500 shadow-xl shadow-indigo-500/20 font-bold">
            {isScanning ? <><i className="ri-loader-4-line animate-spin mr-3"></i>SCANNING SECTOR...</> : <><i className="ri-search-eye-line mr-3"></i>SCAN FOR ANOMALIES</>}
        </Button>
      )}
    </div>
  );

  if (!gameState.currentLocation || gameState.narrativeHistory.length <= 1) {
      return (
          <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans flex flex-col" style={{ width: width || '100%', height: height || '100%' }}>
            {renderInitialization()}
          </div>
      );
  }

  return (
    <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans flex flex-col" style={{ width: width || '100%', height: height || '100%' }}>
        {/* BACKGROUND LAYER */}
        <div className="absolute inset-0 z-0">
            {currentSceneVideoUrl ? (
                <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
            ) : gameState.currentSceneImageUrl ? (
                <img src={gameState.currentSceneImageUrl} alt="Scene" className="w-full h-full object-cover transition-opacity duration-1000 ease-in-out" />
            ) : (
                 <div className="w-full h-full bg-slate-900 flex items-center justify-center">
                    <div className="text-slate-700 animate-pulse text-6xl"><i className="ri-image-line"></i></div>
                 </div>
            )}
            {/* VIGNETTE & GRADIENT OVERLAY */}
            <div className="absolute inset-0 bg-gradient-to-b from-slate-950/90 via-slate-950/20 to-slate-950/90 pointer-events-none"></div>
            <div className="absolute inset-0 bg-black/30 pointer-events-none"></div> 
        </div>

        {/* CONTENT LAYER */}
        <div className="relative z-10 flex flex-col h-full p-2 md:p-4 pointer-events-none overflow-hidden"> 

            {/* TOP BAR: Stats & Controls (RESTORED HUD) */}
            <div className="flex flex-wrap justify-between items-start gap-2 mb-2 pointer-events-auto shrink-0">
                 <div className="bg-slate-950/70 backdrop-blur-md border border-slate-700/50 rounded-lg p-3 shadow-lg flex-grow max-w-full md:max-w-md">
                    <h3 className="text-indigo-300 font-bold text-lg font-cinzel flex items-center gap-2 truncate border-b border-white/10 pb-1 mb-1">
                        <i className="ri-map-pin-user-fill"></i> {gameState.currentLocation}
                    </h3>
                    <div className="flex flex-wrap items-center gap-4 text-xs font-mono text-slate-300">
                         <div className="flex items-center gap-1.5" title="Integrity">
                             <i className="ri-heart-pulse-fill text-rose-500"></i> 
                             <div className="w-16 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                                 <div className="h-full bg-rose-600" style={{ width: `${gameState.vitals?.integrity}%` }}></div>
                             </div>
                             {gameState.vitals?.integrity}%
                         </div>
                         <div className="flex items-center gap-1.5" title="Sanity">
                             <i className="ri-brain-fill text-purple-400"></i>
