import React, { useEffect, useRef } from 'react';

interface Particle {
  x: number;
  y: number;
  size: number;
  color: string;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  type: 'spark' | 'data' | 'glyph'; // Different particle types
  char?: string; // For data particles
}

interface ClickWave {
    x: number;
    y: number;
    radius: number;
    maxRadius: number;
    alpha: number;
    color: string;
    growthRate: number;
    width: number;
    type: 'warp' | 'shockwave' | 'hex';
}

const TECH_COLORS = [
  '#06b6d4', // Cyan
  '#f472b6', // Soft Pink
  '#a78bfa', // Soft Violet
  '#34d399', // Soft Emerald
];

const GLYPH_CHARS = "01"; // Reduced to binary for cleaner look

const MagicalMouseTrail: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const particles = useRef<Particle[]>([]);
  const waves = useRef<ClickWave[]>([]);
  const mouse = useRef({ x: 0, y: 0 });
  const isMouseDown = useRef(false);
  const lastPos = useRef<{x: number, y: number} | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    resize();
    window.addEventListener('resize', resize);

    const handleMouseMove = (e: MouseEvent) => {
      mouse.current = { x: e.clientX, y: e.clientY };

      const speed = lastPos.current ? Math.hypot(e.clientX - lastPos.current.x, e.clientY - lastPos.current.y) : 0;

      // Spawn standard trail particles - Reduced frequency
      if (Math.random() > 0.85) {
        particles.current.push({
          x: e.clientX,
          y: e.clientY,
          size: Math.random() * 1.5 + 0.5,
          color: TECH_COLORS[Math.floor(Math.random() * TECH_COLORS.length)],
          vx: (Math.random() - 0.5) * 0.2,
          vy: (Math.random() - 0.5) * 0.2,
          life: 0.8, // Shorter life
          maxLife: 0.8,
          type: 'spark'
        });
      }

      // Spawn "Drag" effects if mouse is down - Subtle stream
      if (isMouseDown.current && speed > 2) {
         if (Math.random() > 0.5) {
             particles.current.push({
                x: e.clientX + (Math.random()-0.5)*4,
                y: e.clientY + (Math.random()-0.5)*4,
                size: Math.random() * 1.0 + 0.5,
                color: '#ffffff', // Hot white core
                vx: (Math.random() - 0.5) * 0.5,
                vy: (Math.random() - 0.5) * 0.5,
                life: 0.4,
                maxLife: 0.4,
                type: 'data',
                char: undefined
             });
         }
      }

      lastPos.current = { x: e.clientX, y: e.clientY };
    };

    const handleMouseDown = (e: MouseEvent) => {
        isMouseDown.current = true;

        // 1. Precise Ring (Shockwave) - Replaces Warp
        waves.current.push({
            x: e.clientX,
            y: e.clientY,
            radius: 1,
            maxRadius: 60,
            alpha: 0.6,
            color: '#ffffff',
            growthRate: 4,
            width: 1,
            type: 'shockwave'
        });

        // 2. Secondary Echo (Hex/Ring)
        waves.current.push({
            x: e.clientX,
            y: e.clientY,
            radius: 1,
            maxRadius: 40,
            alpha: 0.4,
            color: TECH_COLORS[Math.floor(Math.random() * TECH_COLORS.length)],
            growthRate: 2,
            width: 0.5,
            type: 'hex'
        });

        // 3. Micro Burst
        const burstCount = 6;
        for (let i = 0; i < burstCount; i++) {
            const angle = (Math.PI * 2 * i) / burstCount;
            const speed = 2 + Math.random() * 2;
            particles.current.push({
                x: e.clientX,
                y: e.clientY,
                size: Math.random() * 1.5 + 0.5,
                color: TECH_COLORS[Math.floor(Math.random() * TECH_COLORS.length)],
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                life: 0.6,
                maxLife: 0.6,
                type: 'spark', // Spark type is cleaner than data type for bursts
            });
        }
    };

    const handleMouseUp = () => {
        isMouseDown.current = false;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // -- Draw Waves --
      for (let i = waves.current.length - 1; i >= 0; i--) {
          const wave = waves.current[i];
          wave.radius += wave.growthRate;
          wave.alpha -= 0.02;

          if (wave.alpha <= 0) {
              waves.current.splice(i, 1);
              continue;
          }

          ctx.save();
          // Use lighter blend for subtle glow without inversion
          ctx.globalCompositeOperation = 'lighter';
          ctx.strokeStyle = wave.color;
          ctx.lineWidth = wave.width;
          ctx.globalAlpha = wave.alpha;

          ctx.beginPath();
          if (wave.type === 'hex') {
             // Hexagon approximation
             for(let k=0; k<6; k++) {
                 const angle = k * Math.PI / 3;
                 const hx = wave.x + Math.cos(angle) * wave.radius;
                 const hy = wave.y + Math.sin(angle) * wave.radius;
                 if (k===0) ctx.moveTo(hx, hy); else ctx.lineTo(hx, hy);
             }
             ctx.closePath();
          } else {
             // Circle
             ctx.arc(wave.x, wave.y, wave.radius, 0, Math.PI * 2);
          }
          ctx.stroke();
          ctx.restore();
      }


      // -- Draw Particles --
      ctx.globalCompositeOperation = 'source-over'; 

      // Draw connecting lines for nearby data particles (Cyber-web effect)
      ctx.strokeStyle = 'rgba(100, 255, 255, 0.08)'; // Much fainter
      ctx.lineWidth = 0.5;
      ctx.beginPath(); // Batch line drawing

      for (let i = 0; i < particles.current.length; i++) {
        const p = particles.current[i];

        // Connect nearby particles - Reduced distance check for performance and subtlety
        if (p.type === 'spark') { // Connect sparks too now for continuity
            for (let j = i + 1; j < particles.current.length; j++) {
                const p2 = particles.current[j];
                const dx = p.x - p2.x;
                const dy = p.y - p2.y;
                if (dx*dx + dy*dy < 1600) { // 40px distance squared
                    ctx.moveTo(p.x, p.y);
                    ctx.lineTo(p2.x, p2.y);
                }
            }
        }

        p.x += p.vx;
        p.y += p.vy;
        p.life -= 0.02;
        p.size *= 0.95;

        if (p.life <= 0) {
          particles.current.splice(i, 1);
          i--;
          continue;
        }
      }
      ctx.stroke(); // Draw lines

      // Draw particle bodies
      for (let i = 0; i < particles.current.length; i++) {
        const p = particles.current[i];
        ctx.globalAlpha = p.life * 0.8;
        ctx.fillStyle = p.color;

        if (p.char) {
            ctx.font = `${Math.max(8, p.size * 6)}px monospace`;
            ctx.fillText(p.char, p.x, p.y);
        } else {
           ctx.beginPath();
           if (p.type === 'spark') {
              ctx.rect(p.x - p.size/2, p.y - p.size/2, p.size, p.size); // Square pixels
           } else {
              ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
           }
           ctx.fill();
        }
      }

      ctx.globalAlpha = 1.0;

      requestAnimationFrame(animate);
    };
    animate();

    return () => {
      window.removeEventListener('resize', resize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed inset-0 pointer-events-none z-[9999]"
      style={{ mixBlendMode: 'screen' }} 
    />
  );
};

export default MagicalMouseTrail;

import React, { useEffect, useRef } from 'react';

interface Particle {
  x: number;
  y: number;
  size: number;
  color: string;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  type: 'quantum' | 'bit' | 'wave'; 
  angle?: number;     // For wave motion
  angularSpeed?: number;
}

interface BurstParticle {
    x: number;
    y: number;
    vx: number;
    vy: number;
    size: number;
    color: string;
    life: number;
    rotation: number;
    rotationSpeed: number;
    shape: 'square' | 'triangle' | 'circle';
}

const QUANTUM_COLORS = [
  '#00f0ff', // Electric Cyan
  '#ff0055', // Neon Red/Pink
  '#bd00ff', // Electric Violet
  '#39ff14', // Neon Lime
  '#ffffff', // Pure White core
];

const MagicalMouseTrail: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const particles = useRef<Particle[]>([]);
  const burstParticles = useRef<BurstParticle[]>([]);
  const mouse = useRef({ x: 0, y: 0 });
  const lastPos = useRef<{x: number, y: number} | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    resize();
    window.addEventListener('resize', resize);

    const handleMouseMove = (e: MouseEvent) => {
      mouse.current = { x: e.clientX, y: e.clientY };

      const dist = lastPos.current ? Math.hypot(e.clientX - lastPos.current.x, e.clientY - lastPos.current.y) : 0;

      // Interpolate particles if mouse moves fast for smooth stream
      const steps = Math.min(dist, 10); 
      const startX = lastPos.current ? lastPos.current.x : e.clientX;
      const startY = lastPos.current ? lastPos.current.y : e.clientY;

      for(let i=0; i<=steps; i++) {
        const t = i/steps;
        const x = startX + (e.clientX - startX) * t;
        const y = startY + (e.clientY - startY) * t;

        // Spawn probability based on movement speed - faster = more particles
        if (Math.random() > 0.2) {
            const color = QUANTUM_COLORS[Math.floor(Math.random() * QUANTUM_COLORS.length)];
            const size = Math.random() * 3 + 1; // Larger base size

            particles.current.push({
              x: x + (Math.random()-0.5) * 10, // Slight scatter
              y: y + (Math.random()-0.5) * 10,
              size: size,
              color: color,
              vx: (Math.random() - 0.5) * 1.5,
              vy: (Math.random() - 0.5) * 1.5,
              life: 1.0,
              maxLife: 1.0,
              type: Math.random() > 0.7 ? 'bit' : 'quantum',
              angle: Math.random() * Math.PI * 2,
              angularSpeed: (Math.random() - 0.5) * 0.2
            });
        }
      }

      lastPos.current = { x: e.clientX, y: e.clientY };
    };

    const handleMouseDown = (e: MouseEvent) => {
        // "Superposition Collapse" Burst
        const burstCount = 12;
        for (let i = 0; i < burstCount; i++) {
            const angle = (Math.PI * 2 * i) / burstCount;
            const speed = 4 + Math.random() * 4;
            const color = QUANTUM_COLORS[Math.floor(Math.random() * QUANTUM_COLORS.length)];
            const shapeRoll = Math.random();
            const shape = shapeRoll > 0.6 ? 'square' : shapeRoll > 0.3 ? 'triangle' : 'circle';

            burstParticles.current.push({
                x: e.clientX,
                y: e.clientY,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                size: 5 + Math.random() * 8,
                color: color,
                life: 1.0,
                rotation: Math.random() * Math.PI,
                rotationSpeed: (Math.random() - 0.5) * 0.4,
                shape: shape
            });
        }

        // Add a shockwave ring particle
        particles.current.push({
             x: e.clientX,
             y: e.clientY,
             size: 1,
             color: '#ffffff',
             vx: 0, vy: 0,
             life: 1.0, maxLife: 1.0,
             type: 'wave'
        });
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', () => {}); // No-op but kept for consistency

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Use lighter blending for that glowing quantum feel
      ctx.globalCompositeOperation = 'lighter'; 

      // 1. Update and Draw Burst Particles (Click Effect)
      for (let i = burstParticles.current.length - 1; i >= 0; i--) {
          const p = burstParticles.current[i];
          p.x += p.vx;
          p.y += p.vy;
          p.vx *= 0.92; // Friction
          p.vy *= 0.92;
          p.rotation += p.rotationSpeed;
          p.life -= 0.03;
          p.size *= 0.96;

          if (p.life <= 0) {
              burstParticles.current.splice(i, 1);
              continue;
          }

          ctx.save();
          ctx.translate(p.x, p.y);
          ctx.rotate(p.rotation);
          ctx.fillStyle = p.color;
          ctx.globalAlpha = p.life;

          if (p.shape === 'square') {
              ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
          } else if (p.shape === 'triangle') {
              ctx.beginPath();
              ctx.moveTo(0, -p.size/2);
              ctx.lineTo(p.size/2, p.size/2);
              ctx.lineTo(-p.size/2, p.size/2);
              ctx.closePath();
              ctx.fill();
          } else {
              ctx.beginPath();
              ctx.arc(0, 0, p.size/2, 0, Math.PI * 2);
              ctx.fill();
          }
          ctx.restore();
      }

      // 2. Process Trail Particles
      for (let i = 0; i < particles.current.length; i++) {
        const p = particles.current[i];

        // Quantum Jitter Movement
        p.x += p.vx + Math.sin(p.angle || 0) * 0.5;
        p.y += p.vy + Math.cos(p.angle || 0) * 0.5;
        if(p.angle !== undefined && p.angularSpeed !== undefined) p.angle += p.angularSpeed;

        p.life -= 0.02; // Slower decay for longer trails
        p.size *= 0.97;

        if (p.life <= 0) {
          particles.current.splice(i, 1);
          i--;
          continue;
        }

        // Draw Connections (Entanglement)
        // Connect to nearby particles to create a "mesh"
        // Optimization: only check nearby particles in array index for speed
        if (p.type !== 'wave') {
            for (let j = i + 1; j < Math.min(i + 15, particles.current.length); j++) {
                const p2 = particles.current[j];
                const dx = p.x - p2.x;
                const dy = p.y - p2.y;
                const distSq = dx*dx + dy*dy;

                if (distSq < 3600) { // 60px distance
                    ctx.beginPath();
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = Math.min(2, 600 / distSq) * p.life; // Thicker when closer
                    ctx.globalAlpha = Math.min(1, 1000 / distSq) * 0.3 * p.life; // More opaque when closer
                    ctx.moveTo(p.x, p.y);
                    ctx.lineTo(p2.x, p2.y);
                    ctx.stroke();
                }
            }
        }
      }

      // 3. Draw Particle Bodies
      for (let i = 0; i < particles.current.length; i++) {
        const p = particles.current[i];
        ctx.globalAlpha = p.life;

        if (p.type === 'wave') {
            // Expanding ring for click
            p.size += 5;
            p.life -= 0.02; // Faster decay for ring
            ctx.beginPath();
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.stroke();
        } else if (p.type === 'bit') {
            // Square pixel
            ctx.fillStyle = p.color;
            ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
        } else {
            // Glowing orb
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fillStyle = p.color;
            // Add glow
            ctx.shadowBlur = 10;
            ctx.shadowColor = p.color;
            ctx.fill();
            ctx.shadowBlur = 0; // Reset
        }
      }

      ctx.globalAlpha = 1.0;
      ctx.globalCompositeOperation = 'source-over'; // Reset blend mode

      requestAnimationFrame(animate);
    };
    animate();

    return () => {
      window.removeEventListener('resize', resize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', () => {});
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed inset-0 pointer-events-none z-[9999]"
      style={{ mixBlendMode: 'screen' }} 
    />
  );
};

export default MagicalMouseTrail;

import React, { useEffect, useRef } from 'react';

interface Particle {
  x: number;
  y: number;
  size: number;
  color: string;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  type: 'quantum' | 'bit' | 'wave'; 
  angle?: number;     
  angularSpeed?: number;
}

interface BurstParticle {
    x: number;
    y: number;
    vx: number;
    vy: number;
    size: number;
    color: string;
    life: number;
    rotation: number;
    rotationSpeed: number;
    shape: 'square' | 'triangle' | 'circle';
}

const QUANTUM_COLORS = [
  '#00f0ff', // Electric Cyan
  '#ff0055', // Neon Red/Pink
  '#bd00ff', // Electric Violet
  '#39ff14', // Neon Lime
  '#ffffff', // Pure White core
];

const MagicalMouseTrail: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const particles = useRef<Particle[]>([]);
  const burstParticles = useRef<BurstParticle[]>([]);
  const mouse = useRef({ x: 0, y: 0 });
  const lastPos = useRef<{x: number, y: number} | null>(null);
  const animationFrameRef = useRef<number>(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    resize();
    window.addEventListener('resize', resize);

    const handleMouseMove = (e: MouseEvent) => {
      mouse.current = { x: e.clientX, y: e.clientY };

      const dist = lastPos.current ? Math.hypot(e.clientX - lastPos.current.x, e.clientY - lastPos.current.y) : 0;

      // Interpolate particles if mouse moves fast, but cap it for performance
      const steps = Math.min(dist, 8); 
      const startX = lastPos.current ? lastPos.current.x : e.clientX;
      const startY = lastPos.current ? lastPos.current.y : e.clientY;

      for(let i=0; i<=steps; i++) {
        const t = i/steps;
        const x = startX + (e.clientX - startX) * t;
        const y = startY + (e.clientY - startY) * t;

        // Reduced spawn probability for better performance
        if (Math.random() > 0.4) {
            const color = QUANTUM_COLORS[Math.floor(Math.random() * QUANTUM_COLORS.length)];
            const size = Math.random() * 2 + 1; 

            particles.current.push({
              x: x + (Math.random()-0.5) * 6,
              y: y + (Math.random()-0.5) * 6,
              size: size,
              color: color,
              vx: (Math.random() - 0.5) * 1.0,
              vy: (Math.random() - 0.5) * 1.0,
              life: 1.0,
              maxLife: 1.0,
              type: Math.random() > 0.8 ? 'bit' : 'quantum',
              angle: Math.random() * Math.PI * 2,
              angularSpeed: (Math.random() - 0.5) * 0.1
            });
        }
      }

      lastPos.current = { x: e.clientX, y: e.clientY };

      // Hard cap on particles to prevent memory leaks/lag
      if (particles.current.length > 150) {
        particles.current.splice(0, particles.current.length - 150);
      }
    };

    const handleMouseDown = (e: MouseEvent) => {
        // "Superposition Collapse" Burst
        const burstCount = 8; // Reduced count
        for (let i = 0; i < burstCount; i++) {
            const angle = (Math.PI * 2 * i) / burstCount;
            const speed = 3 + Math.random() * 3;
            const color = QUANTUM_COLORS[Math.floor(Math.random() * QUANTUM_COLORS.length)];
            const shapeRoll = Math.random();
            const shape = shapeRoll > 0.6 ? 'square' : shapeRoll > 0.3 ? 'triangle' : 'circle';

            burstParticles.current.push({
                x: e.clientX,
                y: e.clientY,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                size: 4 + Math.random() * 6,
                color: color,
                life: 1.0,
                rotation: Math.random() * Math.PI,
                rotationSpeed: (Math.random() - 0.5) * 0.4,
                shape: shape
            });
        }

        particles.current.push({
             x: e.clientX,
             y: e.clientY,
             size: 1,
             color: '#ffffff',
             vx: 0, vy: 0,
             life: 1.0, maxLife: 1.0,
             type: 'wave'
        });
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', () => {});

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      ctx.globalCompositeOperation = 'lighter'; 

      // 1. Burst Particles
      for (let i = burstParticles.current.length - 1; i >= 0; i--) {
          const p = burstParticles.current[i];
          p.x += p.vx;
          p.y += p.vy;
          p.vx *= 0.92;
          p.vy *= 0.92;
          p.rotation += p.rotationSpeed;
          p.life -= 0.04; // Faster decay
          p.size *= 0.95;

          if (p.life <= 0) {
              burstParticles.current.splice(i, 1);
              continue;
          }

          ctx.save();
          ctx.translate(p.x, p.y);
          ctx.rotate(p.rotation);
          ctx.fillStyle = p.color;
          ctx.globalAlpha = p.life;

          if (p.shape === 'square') {
              ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
          } else if (p.shape === 'triangle') {
              ctx.beginPath();
              ctx.moveTo(0, -p.size/2);
              ctx.lineTo(p.size/2, p.size/2);
              ctx.lineTo(-p.size/2, p.size/2);
              ctx.closePath();
              ctx.fill();
          } else {
              ctx.beginPath();
              ctx.arc(0, 0, p.size/2, 0, Math.PI * 2);
              ctx.fill();
          }
          ctx.restore();
      }

      // 2. Trail Particles
      for (let i = 0; i < particles.current.length; i++) {
        const p = particles.current[i];

        p.x += p.vx + Math.sin(p.angle || 0) * 0.3;
        p.y += p.vy + Math.cos(p.angle || 0) * 0.3;
        if(p.angle !== undefined && p.angularSpeed !== undefined) p.angle += p.angularSpeed;

        p.life -= 0.025; 
        p.size *= 0.96;

        if (p.life <= 0 || p.size < 0.2) {
          particles.current.splice(i, 1);
          i--;
          continue;
        }

        // Optimized Connections: Only connect to immediate neighbors in the array (Temporal locality)
        // This avoids the O(N^2) loop which causes lag
        if (p.type !== 'wave') {
            // Only check next 5 particles for connections
            const limit = Math.min(i + 5, particles.current.length);
            for (let j = i + 1; j < limit; j++) {
                const p2 = particles.current[j];
                const dx = p.x - p2.x;
                const dy = p.y - p2.y;
                const distSq = dx*dx + dy*dy;

                // 50px distance squared = 2500
                if (distSq < 2500) { 
                    ctx.beginPath();
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 1 * p.life; 
                    ctx.globalAlpha = 0.4 * p.life;
                    ctx.moveTo(p.x, p.y);
                    ctx.lineTo(p2.x, p2.y);
                    ctx.stroke();
                }
            }
        }
      }

      // 3. Draw Bodies (Batch drawing where possible for perf, though styles vary)
      for (let i = 0; i < particles.current.length; i++) {
        const p = particles.current[i];
        ctx.globalAlpha = p.life;

        if (p.type === 'wave') {
            p.size += 3;
            p.life -= 0.03;
            ctx.beginPath();
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 1.5;
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.stroke();
        } else if (p.type === 'bit') {
            ctx.fillStyle = p.color;
            ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
        } else {
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fillStyle = p.color;
            // Only apply shadow blur to larger particles to save perf
            if (p.size > 2) {
                ctx.shadowBlur = 5;
                ctx.shadowColor = p.color;
            } else {
                ctx.shadowBlur = 0;
            }
            ctx.fill();
            ctx.shadowBlur = 0; 
        }
      }

      ctx.globalAlpha = 1.0;
      ctx.globalCompositeOperation = 'source-over'; 

      animationFrameRef.current = requestAnimationFrame(animate);
    };
    animationFrameRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('resize', resize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', () => {});
      cancelAnimationFrame(animationFrameRef.current);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed inset-0 pointer-events-none z-[9999]"
      style={{ mixBlendMode: 'screen' }} 
    />
  );
};

export default MagicalMouseTrail;

import React, { useState, useEffect, useRef } from 'react';
import type { RPGNexusPanelProps, RPGGameState, RPGGameLocation, RPGDynamicAction, RPGSceneData, MarketItem } from '../../types';
import { AgentName, ArtifactType, ArtifactRarity } from '../../types';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { globalSoundEngine } from '../../lib/SoundEngine';
import { QuestCinemaEngine } from '../../lib/video/QuestCinemaEngine';

// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    // Helper to extract JSON object if surrounded by text
    const firstBrace = cleanText.indexOf('{');
    const lastBrace = cleanText.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
        cleanText = cleanText.substring(firstBrace, lastBrace + 1);
    }
    return JSON.parse(cleanText) as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

interface RPGScanResultLocation {
  description: string;
  color?: string;
  risk?: string;
  icon?: string;
}

const FALLBACK_LOCATIONS: Record<string, RPGScanResultLocation> = {
  "The Void Edge": { description: "A precipice where reality dissolves into static.", color: "text-slate-400", risk: "Extreme", icon: "ri-mist-line" },
  "Crystal Spire": { description: "A tower of singing glass reaching into the Aethel.", color: "text-cyan-300", risk: "Low", icon: "ri-building-2-line" },
  "Axiom Forge": { description: "Industrial complex where truths are hammered into shape.", color: "text-amber-400", risk: "Medium", icon: "ri-hammer-line" }
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Scan for Anomalies', type: 'ritual', risk: 0.2, isDynamic: false },
    { id: 'def_rest', label: 'Recalibrate Systems', type: 'talk', risk: 0, isDynamic: false }
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const logContainerRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null,
    sceneHistory: [] 
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");

  // -- Video & Cinema State --
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isCompilingStory, setIsCompilingStory] = useState(false);
  const [compilationProgress, setCompilationProgress] = useState(0);

  // -- Full Screen Media State --
  const [showFullScreenMedia, setShowFullScreenMedia] = useState(false);

  // -- Audio / Narrator State --
  const [isNarratorEnabled, setIsNarratorEnabled] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [currentlyPlayingText, setCurrentlyPlayingText] = useState<string | null>(null);

  // -- Loot State --
  const [foundLoot, setFoundLoot] = useState<MarketItem | null>(null);

  // -- Refs --
  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
        if (audioContextRef.current) audioContextRef.current.close();
    }
  }, []);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  // -- Auto-scroll without page jumping --
  useEffect(() => {
    if (logContainerRef.current) {
        logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
    }
  }, [gameState.narrativeHistory]); 

  const getRiskColor = (risk: number) => {
      if (risk >= 0.7) return 'border-rose-500 hover:bg-rose-900/30 text-rose-200';
      if (risk >= 0.4) return 'border-amber-500 hover:bg-amber-900/30 text-amber-200';
      return 'border-emerald-500 hover:bg-emerald-900/30 text-emerald-200';
  };

  // --- AUDIO HELPER ---
  const playNarrativeAudio = async (text: string) => {
    if (!text) return;
    setIsPlayingAudio(true);
    setCurrentlyPlayingText(text);

    try {
        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        }
        if (audioContextRef.current.state === 'suspended') {
            await audioContextRef.current.resume();
        }

        const audioData = await generateSpeech(text);
        if (audioData) {
            const buffer = await audioContextRef.current.decodeAudioData(audioData);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => {
                setIsPlayingAudio(false);
                setCurrentlyPlayingText(null);
            };
            source.start(0);
        } else {
             // Fallback
             const utterance = new SpeechSynthesisUtterance(text);
             utterance.onend = () => {
                 setIsPlayingAudio(false);
                 setCurrentlyPlayingText(null);
             };
             window.speechSynthesis.speak(utterance);
        }
    } catch (e) {
        console.error("Audio playback error", e);
        setIsPlayingAudio(false);
        setCurrentlyPlayingText(null);
    }
  };


  // --- CORE ENGINE ---

  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    globalSoundEngine.playSFX('click');
    addEchoMessage(AgentName.RPGNexusAgent, "Scanning sector for stability variances...", "text-indigo-300");

    const prompt = `Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting with entropy level ${currentEntropy.toFixed(2)}.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1 sentence)
    - "color": string (Tailwind text class, e.g. "text-red-400")
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class, e.g. "ri-skull-line")`;

    try {
      const response = await invokeGemini(prompt, "You are a JSON generator. Do not include markdown formatting.");
      const locations = cleanAndParseJSON<Record<string, RPGScanResultLocation>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);

      if (isNarratorEnabled) playNarrativeAudio("Sector scan complete. Anomalies detected.");
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: RPGScanResultLocation) => {
    setScanResults(null); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); // Reset video on travel
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const textPrompt = `You are the Game Master. The player has just arrived at "${locationName}" (${locationData.description}).
      Current Entropy: ${currentEntropy}.
      1. Write a vivid, 2-sentence sensory description of the scene.
      2. Provide 3 distinct actions the player can take (Explore, Talk, Analyze, Ritual, etc.).
      3. Create a short quest title related to this location.

      Return JSON:
      {
        "description": "...",
        "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
        "quest": { "title": "...", "description": "...", "rewards": { "xp": 100, "flux": 50 } }
      }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        // Image Gen
        const imagePrompt = `Sci-fi fantasy concept art, ${locationName}, ${textData.description}, cinematic lighting, atmospheric, ${currentEntropy > 0.6 ? 'glitch, chaos, fractal' : 'clean, ethereal, serene'}.`;
        generateImage(imagePrompt).then(url => {
          if (url) {
            setGameState(prev => {
                const newHistoryEntry: RPGSceneData = {
                    imageUrl: url,
                    location: locationName as RPGGameLocation,
                    description: textData.description,
                    timestamp: Date.now()
                };
                return { 
                    ...prev, 
                    currentSceneImageUrl: url,
                    sceneHistory: [...(prev.sceneHistory || []), newHistoryEntry] 
                };
            });
          }
        });

        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions || DEFAULT_ACTIONS,
          activeQuests: prev.activeQuests.length < 3 ? [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }] : prev.activeQuests,
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));

        if (isNarratorEnabled) playNarrativeAudio(textData.description);
      }
    } catch (e) {
      console.error("Travel generation failed", e);
      addEchoMessage(AgentName.System, "Navigational data corrupted. Using fallback protocols.", "text-rose-400");
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); 
    setFoundLoot(null); // Reset loot view
    globalSoundEngine.playSFX('click');

    setGameState(prev => ({
        ...prev,
        narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${actionLabel}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})
    Current Scene: ${gameState.currentSceneDescription}

    Determine the outcome. 
    1. Write a 1-2 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. PROVIDE 3 NEW Available Actions for the player based on the new situation.
    4. Decide if a loot item (Card) is found (20% chance). If yes, provide "lootItem" details.

    Return JSON:
    {
      "resultText": "...",
      "deltaIntegrity": -5, 
      "deltaSanity": 0,
      "deltaFlux": 10,
      "newActions": [ { "id": "new_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
      "lootItem": { "name": "...", "rarity": "Common|Rare|Legendary", "type": "Relic", "description": "..." } (OPTIONAL)
    }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only. Do not wrap in markdown.");
        const outcome = cleanAndParseJSON<any>(response);

        if (outcome) {
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));

            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: (outcome.newActions && outcome.newActions.length > 0) ? outcome.newActions : DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));

            if (outcome.deltaFlux && onUpdateProfile && activeProfile) {
                onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + outcome.deltaFlux });
                addEchoMessage(AgentName.RPGNexusAgent, `Flux ${outcome.deltaFlux > 0 ? '+' : ''}${outcome.deltaFlux}`, outcome.deltaFlux > 0 ? 'text-amber-300' : 'text-rose-400');
            }

            // Handle Loot Generation (don't add to inventory yet)
            if (outcome.lootItem) {
                const newItem: MarketItem = {
                    id: `loot-${Date.now()}`,
                    name: outcome.lootItem.name,
                    type: outcome.lootItem.type || 'Relic',
                    rarity: outcome.lootItem.rarity || ArtifactRarity.Common,
                    description: outcome.lootItem.description || "An interesting find.",
                    visualPromptMod: "artifact",
                    cost: 100, // Nominal value
                    icon: 'ri-treasure-map-line'
                };
                setFoundLoot(newItem);
                // NOT adding to profile inventory here anymore, waiting for user confirmation via UI

                addEchoMessage(AgentName.RPGNexusAgent, `Loot Discovered: ${newItem.name}. Examine to acquire.`, 'text-cyan-300');

                // Optionally generate visual memory artifact of the discovery event itself
                if (onArtifactCreated) {
                     onArtifactCreated({
                        id: newItem.id,
                        name: newItem.name,
                        type: ArtifactType.RitualResidue,
                        rarity: newItem.rarity,
                        description: newItem.description,
                        timestamp: Date.now()
                    });
                }
                globalSoundEngine.playSFX('success');
            }

            if (risk > 0.5) onUpdateSystemMetrics(0.01, -0.01); 
            if (isNarratorEnabled) playNarrativeAudio(outcome.resultText);

        } else {
             setGameState(prev => ({
                ...prev,
                availableActions: DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: "The ether churns, obscuring the outcome. (Data corruption)", type: 'system', timestamp: Date.now() }]
            }));
        }
    } catch (e) {
        addEchoMessage(AgentName.System, "Action resolution failed. Systems rebooting...", "text-rose-400");
        setGameState(prev => ({ ...prev, availableActions: DEFAULT_ACTIONS }));
    } finally {
        setIsProcessingTurn(false);
    }
  };

  // --- NEW FEATURES ---

  const handleGenerateSceneVideo = async () => {
      if (isAnimatingScene || !gameState.currentSceneImageUrl) return;
      setIsAnimatingScene(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Animating scene via Veo-3.1...", "text-fuchsia-300");

      try {
          const prompt = `Cinematic subtle motion, atmospheric video of ${gameState.currentSceneDescription}. ${currentEntropy > 0.6 ? 'Glitch art style, disturbing movement.' : 'Serene, flowing motion.'}`;
          const videoUrl = await generateVideo(prompt, gameState.currentSceneImageUrl);
          if (videoUrl) {
              setCurrentSceneVideoUrl(videoUrl);
              addEchoMessage(AgentName.RPGNexusAgent, "Scene animation compiled.", "text-emerald-300");
          } else {
              throw new Error("No video URL returned.");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Video generation failed.", "text-rose-400");
      } finally {
          setIsAnimatingScene(false);
      }
  };

  const handleCompileStoryVideo = async () => {
      if (isCompilingStory || !gameState.sceneHistory || gameState.sceneHistory.length === 0) {
          addEchoMessage(AgentName.System, "No scene history to compile.", "text-yellow-400");
          return;
      }

      setIsCompilingStory(true);
      setCompilationProgress(0);
      addEchoMessage(AgentName.RPGNexusAgent, "Compiling narrative history into Quest Cinema...", "text-amber-300");

      try {
          if (!cinemaEngineRef.current) {
              cinemaEngineRef.current = new QuestCinemaEngine();
          }

          const slides = gameState.sceneHistory.map(scene => ({
              imageUrl: scene.imageUrl,
              text: scene.description
          }));

          const blob = await cinemaEngineRef.current.compileVideo(
              slides,
              (progress) => setCompilationProgress(Math.round(progress * 100)),
              async (text) => await generateSpeech(text) 
          );

          if (blob) {
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `Nexus_Story_${Date.now()}.webm`; 
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              addEchoMessage(AgentName.RPGNexusAgent, "Story Compilation Complete. Downloading...", "text-emerald-300");

              if (onArtifactCreated) {
