                            Add to Inventory
                        </Button>
                    </div>
                )}
            </div>

            {/* Full Screen Media Overlay */}
            {showFullScreenMedia && (currentSceneVideoUrl || gameState.currentSceneImageUrl) && (
                <div className="fixed inset-0 z-[9999] bg-black/95 backdrop-blur-md flex flex-col items-center justify-center pointer-events-auto animate-fade-in-up">
                    <button 
                        onClick={() => setShowFullScreenMedia(false)} 
                        className="absolute top-4 right-4 text-white hover:text-rose-400 transition-colors z-50"
                        title="Close Full Screen"
                    >
                        <i className="ri-close-circle-line text-4xl"></i>
                    </button>

                    <div className="flex-grow w-full h-full flex items-center justify-center p-4">
                        {currentSceneVideoUrl ? (
                            <video 
                                src={currentSceneVideoUrl} 
