import React, { useState, useEffect } from 'react';
import type { SeekerProfile, RPGGameState, CodexArtifact } from '../../types';
import { AgentName, ArtifactType, ArtifactRarity, CodexModeId } from '../../types';
import { AGENT_PROFILES } from '../../constants';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';

interface RPGNexusPanelProps {
  width: number | string;
  height: number | string;
  addEchoMessage: (source: string, text: string, colorClass?: string) => void;
  activeProfile: SeekerProfile | null;
  onUpdateProfile: (profile: SeekerProfile) => void;
  currentEntropy: number;
  systemMode: CodexModeId;
  onArtifactCreated: (artifact: CodexArtifact) => void;
  artifacts: CodexArtifact[];
  savedState: RPGGameState | undefined;
  onSaveState: (state: RPGGameState) => void;
  onUpdateSystemMetrics: (entropyDelta: number, negentropyDelta: number) => void;
}

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  systemMode,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, isGenerating } = useGemini();
  const [currentScene, setCurrentScene] = useState<string>("The Nexus is quiet. Initialize your seeker to begin.");
  const [availableActions, setAvailableActions] = useState<{id: string, label: string}[]>([
    { id: 'explore', label: 'Explore the Void' },
    { id: 'meditate', label: 'Meditate on Axioms' }
  ]);
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'Nexus Hub',
    currentSceneDescription: 'You stand at the center of the Codex, where all threads converge.',
    activeQuests: [],
    vitals: { integrity: 100, sanity: 100 },
    history: []
  });

  useEffect(() => {
    if (savedState) {
        setGameState(savedState);
        setCurrentScene(savedState.currentSceneDescription);
    }
  }, [savedState]);

  const handleAction = async (actionId: string, actionLabel: string) => {
    if (isGenerating || !activeProfile) return;

    // Optimistic UI update
    const tempScene = `...attempting to ${actionLabel.toLowerCase()}...`;
    setCurrentScene(tempScene);

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${actionLabel}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})
    Current Scene: ${gameState.currentSceneDescription}
    System Mode: ${systemMode}

    Determine the outcome. 
    1. Write a 2-3 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. PROVIDE 3 NEW Available Actions for the player based on the new situation.
    4. Decide if a loot item (Artifact) is found (20% chance). If yes, provide "lootItem" details.

    Return JSON format only:
    {
      "resultText": "string",
      "deltaIntegrity": number, 
      "deltaSanity": number,
      "deltaFlux": number,
      "deltaEntropy": number,
      "newActions": [ { "id": "string", "label": "string" }, ... ],
      "lootItem": { "name": "string", "rarity": "Common|Rare|Legendary|Mythic", "type": "Relic|Weapon|Consumable", "description": "string" } | null
    }`;

    try {
        const response = await invokeGemini(prompt, "You are the Dungeon Master of the Tri-Sophian Codex. Respond in valid JSON only.");
        if (!response) throw new Error("No response from GM.");

        // Clean up markdown code blocks if present
        const jsonStr = response.replace(/```json/g, '').replace(/```/g, '').trim();
        const result = JSON.parse(jsonStr);

        // Update State
        const newIntegrity = Math.min(100, Math.max(0, (gameState.vitals?.integrity || 100) + (result.deltaIntegrity || 0)));
        const newSanity = Math.min(100, Math.max(0, (gameState.vitals?.sanity || 100) + (result.deltaSanity || 0)));

        const newState: RPGGameState = {
            ...gameState,
            currentSceneDescription: result.resultText,
            vitals: { integrity: newIntegrity, sanity: newSanity },
            history: [...(gameState.history || []), { action: actionLabel, result: result.resultText, timestamp: Date.now() }]
        };

        setGameState(newState);
        setCurrentScene(result.resultText);
        setAvailableActions(result.newActions || []);
        onSaveState(newState);

        // Update Profile Stats
        if (result.deltaFlux) {
            onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + result.deltaFlux, experience: activeProfile.experience + 10 });
        }

        // Update System Metrics
        if (result.deltaEntropy) {
             onUpdateSystemMetrics(result.deltaEntropy, 0); // Negentropy ignored for now
        }

        // Handle Loot
        if (result.lootItem) {
            const newArtifact: CodexArtifact = {
                id: `loot-${Date.now()}`,
                name: result.lootItem.name,
                type: result.lootItem.type,
                rarity: result.lootItem.rarity as ArtifactRarity,
                description: result.lootItem.description,
                timestamp: Date.now()
            };
            onArtifactCreated(newArtifact);
            addEchoMessage(AgentName.RPGNexusAgent, `Loot Found: ${newArtifact.name} (${newArtifact.rarity})`, 'text-amber-300');
        }

        addEchoMessage(AgentName.RPGNexusAgent, `Action: ${actionLabel} -> ${result.resultText.substring(0, 50)}...`, 'text-indigo-300');

    } catch (e) {
        console.error("GM Error:", e);
        addEchoMessage(AgentName.System, "The GM Core glitched. Connection unstable.", 'text-rose-400');
        setCurrentScene(gameState.currentSceneDescription); // Revert
    }
  };

  return (
    <div className="rpg-nexus-panel bg-slate-950/95 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl p-4 flex flex-col" style={{ width: width || '100%', height: height || '600px' }}>
      <div className="flex justify-between items-center mb-4 border-b border-indigo-800/50 pb-2">
        <h3 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center">
            <i className="ri-gamepad-line mr-2"></i>Nexus Engine
        </h3>
        <div className="text-xs font-mono text-slate-400">
            {activeProfile ? `${activeProfile.name} [Lvl ${activeProfile.level}]` : "No Active Profile"}
        </div>
      </div>

      <div className="flex-grow flex flex-col gap-4 overflow-hidden">
        {/* Scene Display */}
        <div className="bg-slate-900/60 p-4 rounded-lg border border-slate-700/50 flex-grow overflow-y-auto custom-scrollbar">
             <p className="text-slate-200 font-cormorant text-lg leading-relaxed whitespace-pre-wrap animate-fade-in-up">
                 {currentScene}
             </p>
             {isGenerating && <div className="mt-2 text-indigo-400 animate-pulse text-sm">The Dungeon Master is thinking...</div>}
        </div>

        {/* Actions */}
        <div className="shrink-0 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
            {availableActions.map((action, idx) => (
                <Button 
                    key={idx} 
                    onClick={() => handleAction(action.id, action.label)}
                    disabled={isGenerating || !activeProfile}
                    className="w-full text-sm py-3 bg-slate-800 hover:bg-indigo-700 border border-slate-600 hover:border-indigo-500 transition-all text-slate-200"
                >
                    {action.label}
                </Button>
            ))}
        </div>

        {/* Status Bar */}
        <div className="shrink-0 bg-slate-900/40 p-2 rounded border border-slate-800 flex justify-between text-xs font-mono text-slate-400">
            <span>Location: <span className="text-indigo-200">{gameState.currentLocation}</span></span>
            <span>Integrity: <span className={gameState.vitals?.integrity && gameState.vitals.integrity < 30 ? 'text-red-400' : 'text-emerald-400'}>{gameState.vitals?.integrity}%</span></span>
            <span>Sanity: <span className={gameState.vitals?.sanity && gameState.vitals.sanity < 30 ? 'text-purple-400' : 'text-blue-400'}>{gameState.vitals?.sanity}%</span></span>
        </div>
      </div>
    </div>
  );
};

export default RPGNexusPanel;

import { 
  AgentNode, AgentStats, AgentRelationships, GridPoint, 
  AgentRace, AgentLineage, AgentTrade, AgentFaction 
} from '../types';
import { ALL_RACES_LIST, ALL_LINEAGES_LIST, ALL_TRADES_LIST, ALL_FACTIONS_LIST, TRAIT_LISTS } from '../constants';

const getRandomElement = <T>(arr: T[]): T => arr[Math.floor(Math.random() * arr.length)];

const generateStats = (): AgentStats => ({
  cognition: Math.random(),
  vitality: Math.random(),
  aether: Math.random(),
  presence: Math.random(),
  paradox: Math.random(),
  will: Math.random(),
  resonance: Math.random(),
  chaosStability: Math.random(),
});

export const generateProceduralAgent = (id: string, position: GridPoint): AgentNode => {
  const race = getRandomElement(ALL_RACES_LIST) as AgentRace;
  const lineage = getRandomElement(ALL_LINEAGES_LIST) as AgentLineage;
  const trade = getRandomElement(ALL_TRADES_LIST) as AgentTrade;
  // Simple logic to pick a faction, maybe based on race later, for now random but weighted could be cool
  const faction = getRandomElement(ALL_FACTIONS_LIST) as AgentFaction; 

  const traits: string[] = [];
  for (let i = 0; i < 3; i++) traits.push(getRandomElement(TRAIT_LISTS.self));

  const codexTraits: string[] = [];
  for (let i = 0; i < 2; i++) codexTraits.push(getRandomElement(TRAIT_LISTS.codex));

  const stats = generateStats();

  // Basic color mapping based on Faction for visual distinction
  let color = '#FFFFFF';
  switch (faction) {
    case AgentFaction.TrisophianSynod: color = '#38bdf8'; break; // Sky blue
    case AgentFaction.ObsidianChoir: color = '#475569'; break; // Slate
    case AgentFaction.ChronoDominion: color = '#fbbf24'; break; // Amber
    case AgentFaction.VoidChorus: color = '#a855f7'; break; // Purple
    case AgentFaction.AxiomForgeGuild: color = '#f97316'; break; // Orange
    case AgentFaction.SolarContinuum: color = '#facc15'; break; // Yellow
    case AgentFaction.DreamshellCollective: color = '#ec4899'; break; // Pink
    default: color = '#94a3b8'; // Neutral
  }

  return {
    id,
    name: `Agent ${id.split('-')[1]}`, // Simplified name
    race,
    lineage,
    trade,
    faction,
    traits: Array.from(new Set(traits)), // Unique traits
    codexTraits: Array.from(new Set(codexTraits)),
    stats,
    relationships: { allies: [], rivals: [], neutral: [] },
    harmony: (stats.resonance + stats.chaosStability) / 2, // Derived harmony
    position,
    active: true,
    pulsePhase: Math.random() * Math.PI * 2,
    color,
    icon: 'ri-user-line' // Could map icon to Trade later
  };
};

export const calculateAffinity = (agentA: AgentNode, agentB: AgentNode): number => {
  let score = 0;

  // Faction Alignment
  if (agentA.faction === agentB.faction) score += 0.5;

  // Lineage Resonance
  if (agentA.lineage === agentB.lineage) score += 0.3;
  // Specific Lineage Paradoxes (Example)
  if ((agentA.lineage === AgentLineage.VoidTouched && agentB.lineage === AgentLineage.LuminousPrecursor) ||
      (agentB.lineage === AgentLineage.VoidTouched && agentA.lineage === AgentLineage.LuminousPrecursor)) {
      score -= 0.8; // High paradox chance
  }

  // Trait Synergy (simplified matching)
  const sharedTraits = agentA.traits.filter(t => agentB.traits.includes(t));
  score += sharedTraits.length * 0.1;

  // Stat Compatibility (e.g., similar resonance levels)
  const resonanceDiff = Math.abs(agentA.stats.resonance - agentB.stats.resonance);
  if (resonanceDiff < 0.1) score += 0.2;

  return score;
};

export const processAgentInteractions = (agents: AgentNode[]): AgentNode[] => {
  const updatedAgents = [...agents];

  // Simple O(N^2) for demo purposes, optimize with spatial partitioning if N > 500
  for (let i = 0; i < updatedAgents.length; i++) {
    for (let j = i + 1; j < updatedAgents.length; j++) {
      const a = updatedAgents[i];
      const b = updatedAgents[j];

      // Check distance (interaction range)
      const dist = Math.sqrt(Math.pow(a.position[0] - b.position[0], 2) + Math.pow(a.position[1] - b.position[1], 2));

      if (dist < 2) { // Adjacent or same cell
        const affinity = calculateAffinity(a, b);
        const timestamp = Date.now();

        // Define Relationship Update Logic
        const updateRelationship = (agent: AgentNode, targetId: string, aff: number) => {
            const rels = { ...agent.relationships };
            // Clear previous status
            rels.allies = rels.allies.filter(id => id !== targetId);
            rels.rivals = rels.rivals.filter(id => id !== targetId);
            rels.neutral = rels.neutral.filter(id => id !== targetId);

            let type: 'Synergy' | 'Paradox' | 'Neutral' = 'Neutral';
            if (aff > 0.6) {
                rels.allies.push(targetId);
                type = 'Synergy';
            } else if (aff < -0.2) {
                rels.rivals.push(targetId);
                type = 'Paradox';
            } else {
                rels.neutral.push(targetId);
            }

            rels.lastInteraction = {
                agentId: targetId,
                type,
                description: type === 'Synergy' ? 'Harmonic Resonance' : (type === 'Paradox' ? 'Dissonant Clash' : 'Passing Observation'),
                timestamp
            };
            return rels;
        };

        updatedAgents[i] = { ...a, relationships: updateRelationship(a, b.id, affinity) };
        updatedAgents[j] = { ...b, relationships: updateRelationship(b, a.id, affinity) };
      }
    }
  }
  return updatedAgents;
};

