const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  onArtifactCreated,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const logContainerRef = useRef<HTMLDivElement>(null);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [],
    currentSceneDescription: "The initialization void. Static fills the air.",
    currentSceneImageUrl: null,
    sceneHistory: [] 
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");

  // -- Video & Cinema State --
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isCompilingStory, setIsCompilingStory] = useState(false);
  const [compilationProgress, setCompilationProgress] = useState(0);

  // -- View Mode State --
  const [viewMode, setViewMode] = useState<'scene' | 'map'>('scene');

  // -- Full Screen Media State --
  const [showFullScreenMedia, setShowFullScreenMedia] = useState(false);

  // -- Audio / Narrator State --
  const [isNarratorEnabled, setIsNarratorEnabled] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [currentlyPlayingText, setCurrentlyPlayingText] = useState<string | null>(null);

  // -- Loot State --
  const [foundLoot, setFoundLoot] = useState<MarketItem | null>(null);

  // -- Refs --
  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
        if (audioContextRef.current) audioContextRef.current.close();
    }
  }, []);

  // -- Persistence --
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  // -- Auto-scroll without page jumping --
  useEffect(() => {
    if (logContainerRef.current) {
        logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
    }
  }, [gameState.narrativeHistory]); 

  const getRiskColor = (risk: number) => {
      if (risk >= 0.7) return 'border-rose-500 hover:bg-rose-900/30 text-rose-200';
      if (risk >= 0.4) return 'border-amber-500 hover:bg-amber-900/30 text-amber-200';
      return 'border-emerald-500 hover:bg-emerald-900/30 text-emerald-200';
  };

  // --- AUDIO HELPER ---
  const playNarrativeAudio = async (text: string) => {
    if (!text) return;
    setIsPlayingAudio(true);
    setCurrentlyPlayingText(text);

    try {
        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        }
        if (audioContextRef.current.state === 'suspended') {
            await audioContextRef.current.resume();
        }

        const audioData = await generateSpeech(text);
        if (audioData) {
            const buffer = await audioContextRef.current.decodeAudioData(audioData);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => {
                setIsPlayingAudio(false);
                setCurrentlyPlayingText(null);
            };
            source.start(0);
        } else {
             // Fallback
             const utterance = new SpeechSynthesisUtterance(text);
             utterance.onend = () => {
                 setIsPlayingAudio(false);
                 setCurrentlyPlayingText(null);
             };
             window.speechSynthesis.speak(utterance);
        }
    } catch (e) {
        console.error("Audio playback error", e);
        setIsPlayingAudio(false);
        setCurrentlyPlayingText(null);
    }
  };


  // --- CORE ENGINE ---

  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    setViewMode('scene'); // Switch back to scene view to see results
    globalSoundEngine.playSFX('click');
    addEchoMessage(AgentName.RPGNexusAgent, "Scanning sector for stability variances...", "text-indigo-300");

    const themes = QUEST_THEMES.join(", ");
    const prompt = `Generate 3 unique, evocative RPG locations for a setting with entropy level ${currentEntropy.toFixed(2)}.
    Mix these themes: ${themes}.
    For 'Headphone Hero' themes, include locations involving sonic weaponry or alien audio artifacts.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1 sentence)
    - "color": string (Tailwind text class, e.g. "text-red-400")
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class, e.g. "ri-skull-line")
    - "genre": string (One of the themes used)`;

    try {
      const response = await invokeGemini(prompt, "You are a JSON generator. Do not include markdown formatting.");
      const locations = cleanAndParseJSON<Record<string, RPGScanResultLocation>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);

      if (isNarratorEnabled) playNarrativeAudio("Sector scan complete. Anomalies detected.");
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: Partial<RPGScanResultLocation>) => {
    setScanResults(null); 
    setViewMode('scene'); // Ensure we are in scene view
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); // Reset video on travel
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const textPrompt = `You are the Game Master for a ${locationData.genre || 'Sci-Fi'} adventure. The player has just arrived at "${locationName}" (${locationData.description || 'Unknown location'}).
      Current Entropy: ${currentEntropy}.
      1. Write a vivid, 2-sentence sensory description of the scene.
      2. Provide 3 distinct actions the player can take (Explore, Talk, Analyze, Ritual, Combat, etc.).
      3. Create a short quest title related to this location.

      Return JSON:
      {
        "description": "...",
        "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
        "quest": { "title": "...", "description": "...", "rewards": { "xp": 100, "flux": 50 } }
      }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        // Image Gen with Character Injection
        const characterDesc = getCharacterVisualPrompt(activeProfile);
        const imagePrompt = `Epic Concept Art, ${locationData.genre || 'Sci-Fi'} style. Subject: ${characterDesc}. Action: Standing amidst ${locationName}. Environment: ${textData.description}. Style: ${activeProfile?.visualFilter || 'cinematic'}, atmospheric lighting, highly detailed.`;

        generateImage(imagePrompt).then(url => {
          if (url) {
            setGameState(prev => {
                const newHistoryEntry: RPGSceneData = {
                    imageUrl: url,
                    location: locationName as RPGGameLocation,
                    description: textData.description,
                    timestamp: Date.now()
                };
                return { 
                    ...prev, 
                    currentSceneImageUrl: url,
                    sceneHistory: [...(prev.sceneHistory || []), newHistoryEntry] 
                };
            });
          }
        });

        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions || DEFAULT_ACTIONS,
          activeQuests: prev.activeQuests.length < 3 ? [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }] : prev.activeQuests,
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));

        if (isNarratorEnabled) playNarrativeAudio(textData.description);
      }
    } catch (e) {
      console.error("Travel generation failed", e);
      addEchoMessage(AgentName.System, "Navigational data corrupted. Using fallback protocols.", "text-rose-400");
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); 
    setFoundLoot(null); // Reset loot view
    globalSoundEngine.playSFX('click');

    setGameState(prev => ({
        ...prev,
        narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    const prompt = `Game Master Logic:
    Location: ${gameState.currentLocation}
    Action Taken: "${actionLabel}"
    Entropy: ${currentEntropy}
    Profile: ${activeProfile?.name || "Seeker"} (${activeProfile?.race} ${activeProfile?.class})${activeProfile?.class === 'HeadphoneHero' ? ' [Note: This class uses Alien Headphones that grant sonic superpowers]' : ''}
    Current Scene: ${gameState.currentSceneDescription}

    Determine the outcome. 
    1. Write a 1-2 sentence narrative result.
    2. Define any stat changes (integrity/sanity/flux).
    3. PROVIDE 3 NEW Available Actions for the player based on the new situation.
    4. Decide if a loot item (Card) is found (20% chance). If yes, provide "lootItem" details.

    Return JSON:
    {
      "resultText": "...",
      "deltaIntegrity": -5, 
      "deltaSanity": 0,
      "deltaFlux": 10,
      "newActions": [ { "id": "new_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ],
      "lootItem": { "name": "...", "rarity": "Common|Rare|Legendary", "type": "Relic", "description": "..." } (OPTIONAL)
    }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only. Do not wrap in markdown.");
        const outcome = cleanAndParseJSON<any>(response);

        if (outcome) {
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));

            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: (outcome.newActions && outcome.newActions.length > 0) ? outcome.newActions : DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));

            if (outcome.deltaFlux && onUpdateProfile && activeProfile) {
                onUpdateProfile({ ...activeProfile, flux: activeProfile.flux + outcome.deltaFlux });
                addEchoMessage(AgentName.RPGNexusAgent, `Flux ${outcome.deltaFlux > 0 ? '+' : ''}${outcome.deltaFlux}`, outcome.deltaFlux > 0 ? 'text-amber-300' : 'text-rose-400');
            }

            // Auto-Generate Art for Action Outcome
            const characterDesc = getCharacterVisualPrompt(activeProfile);
            const actionImagePrompt = `Fantasy Sci-Fi Art. Subject: ${characterDesc} performing action: ${actionLabel}. Outcome: ${outcome.resultText}. Location: ${gameState.currentLocation}. Style: ${activeProfile?.visualFilter || 'cinematic'}, action shot, dynamic lighting.`;

            generateImage(actionImagePrompt).then(url => {
                 if (url) {
                    setGameState(prev => {
                        // Create history entry for the action visual too
                        const newHistoryEntry: RPGSceneData = {
                            imageUrl: url,
                            location: prev.currentLocation,
                            description: outcome.resultText,
                            timestamp: Date.now()
                        };
                        return { 
                            ...prev, 
                            currentSceneImageUrl: url, // Update main view
                            sceneHistory: [...(prev.sceneHistory || []), newHistoryEntry] 
                        };
                    });
                    // Reset video if new static image generated
                    setCurrentSceneVideoUrl(null); 
                 }
            });

            // Handle Loot Generation
            if (outcome.lootItem) {
                const newItem: MarketItem = {
                    id: `loot-${Date.now()}`,
                    name: outcome.lootItem.name,
                    type: outcome.lootItem.type || 'Relic',
                    rarity: outcome.lootItem.rarity || ArtifactRarity.Common,
                    description: outcome.lootItem.description || "An interesting find.",
                    visualPromptMod: "artifact",
                    cost: 100, // Nominal value
                    icon: 'ri-treasure-map-line'
                };
                setFoundLoot(newItem);

                addEchoMessage(AgentName.RPGNexusAgent, `Loot Discovered: ${newItem.name}. Examine to acquire.`, 'text-cyan-300');

                if (onArtifactCreated) {
                     onArtifactCreated({
                        id: newItem.id,
                        name: newItem.name,
                        type: ArtifactType.RitualResidue,
                        rarity: newItem.rarity,
                        description: newItem.description,
                        timestamp: Date.now()
                    });
                }
                globalSoundEngine.playSFX('success');
            }

            if (risk > 0.5) onUpdateSystemMetrics(0.01, -0.01); 
            if (isNarratorEnabled) playNarrativeAudio(outcome.resultText);

        } else {
             setGameState(prev => ({
                ...prev,
                availableActions: DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: "The ether churns, obscuring the outcome. (Data corruption)", type: 'system', timestamp: Date.now() }]
            }));
        }
    } catch (e) {
        addEchoMessage(AgentName.System, "Action resolution failed. Systems rebooting...", "text-rose-400");
        setGameState(prev => ({ ...prev, availableActions: DEFAULT_ACTIONS }));
    } finally {
        setIsProcessingTurn(false);
    }
  };

  const handleEndQuest = () => {
    if (confirm("End current quest sequence? This will archive your journey and reset the Nexus.")) {
        // Archive Logic
        if (onArtifactCreated && gameState.sceneHistory && gameState.sceneHistory.length > 0) {
            onArtifactCreated({
                id: `chronicle-${Date.now()}`,
                name: `Chronicle: ${gameState.currentLocation || 'Unknown Vector'}`,
                type: ArtifactType.VisualMemory,
                rarity: ArtifactRarity.Rare,
                description: `Completed adventure log. ${gameState.narrativeHistory.length} entries recorded in ${gameState.currentLocation}.`,
                imageUrl: gameState.currentSceneImageUrl || "",
                timestamp: Date.now()
            });
        }

        // Reset State
        setGameState({
            currentLocation: 'The Void Edge', // Reset to default to trigger init logic
            narrativeHistory: [{ text: "System Reset. Nexus Engine awaiting new insertion vector...", type: 'system', timestamp: Date.now() }],
            activeQuests: [],
            lastActionTimestamp: Date.now(),
            vitals: { integrity: 100, sanity: 100 },
            availableActions: DEFAULT_ACTIONS,
            achievements: gameState.achievements, // Keep achievements
            combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
            knownLocations: gameState.knownLocations, // Keep discovered locations
            currentSceneDescription: "The initialization void. Static fills the air.",
            currentSceneImageUrl: null,
            sceneHistory: []
        });
        setScanResults(null);
        setFoundLoot(null);
        setCurrentSceneVideoUrl(null);
        setViewMode('scene');
        addEchoMessage(AgentName.System, "Quest Concluded. Nexus State Archived & Reset.", "text-emerald-400");
        globalSoundEngine.playSFX('pulse');
    }
