// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    // Helper to extract JSON object if surrounded by text
    const firstBrace = cleanText.indexOf('{');
    const lastBrace = cleanText.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
        cleanText = cleanText.substring(firstBrace, lastBrace + 1);
    }
    return JSON.parse(cleanText) as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

// --- Helper: Character Visual Prompt Builder ---
const getCharacterVisualPrompt = (profile: any | null): string => {
    if (!profile) return "A mysterious hooded figure";

    const equipment = [];
    if (profile.equippedOutfit) equipment.push(profile.equippedOutfit.name);
    if (profile.equippedWeapon) equipment.push(profile.equippedWeapon.name);

    return `A ${profile.gender} ${profile.race} ${profile.class}${equipment.length > 0 ? `, wearing ${equipment.join(' and ')}` : ''}, glowing with a ${profile.auraColor || 'faint'} aura${profile.class === 'HeadphoneHero' ? ', wearing glowing high-tech alien headphones' : ''}`;
};

