                            title={viewMode === 'scene' ? "Open Star Map" : "Return to Scene"}
                        >
                             <i className={`ri-${viewMode === 'scene' ? 'map-2' : 'landscape'}-line text-lg`}></i>
                        </button>

                        <button 
                            onClick={handleCompileStoryVideo} 
                            disabled={isCompilingStory || !gameState.sceneHistory?.length}
                            className={`bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border transition-all ${isCompilingStory ? 'border-amber-500 text-amber-400 animate-pulse' : 'border-slate-600/50 text-slate-400 hover:text-white'}`}
                            title="Compile Quest Reel (Movie)"
                        >
                            <i className="ri-movie-2-line text-lg"></i>
                        </button>

                        <button 
                            onClick={handleDownloadStory}
                            className="bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border border-slate-600/50 text-slate-400 hover:text-white transition-all"
                            title="Export Story Log"
                        >
                            <i className="ri-file-text-line text-lg"></i>
                        </button>

                        <button
                            onClick={() => setIsNarratorEnabled(!isNarratorEnabled)}
                            className={`bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border transition-all ${isNarratorEnabled ? 'border-emerald-500 text-emerald-400' : 'border-slate-600/50 text-slate-400 hover:text-white'}`}
                            title={isNarratorEnabled ? "Disable Narrator" : "Enable Narrator Mode"}
                        >
                            <i className={`ri-volume-${isNarratorEnabled ? 'up' : 'mute'}-line text-lg`}></i>
                        </button>
                    </div>

                    {/* Scene Specific Group */}
                    {viewMode === 'scene' && (
                    <div className="flex gap-1 ml-1 border-l border-slate-700/50 pl-1">
                        <button 
                            onClick={() => setShowFullScreenMedia(true)}
                            disabled={!currentSceneVideoUrl && !gameState.currentSceneImageUrl}
                            className="bg-slate-950/70 hover:bg-cyan-900/60 backdrop-blur-md text-white p-3 rounded-lg border border-slate-600/50 transition-all"
                            title="View Full Scene"
                        >
                            <i className="ri-eye-line text-lg"></i>
                        </button>
                        <button 
                            onClick={handleReimagineScene}
                            disabled={isProcessingTurn}
                            className="bg-slate-950/70 hover:bg-purple-900/60 backdrop-blur-md text-white p-3 rounded-lg border border-slate-600/50 transition-all"
                            title="Reimagine Scene"
                        >
                            <i className={`ri-refresh-line text-lg ${isProcessingTurn ? 'animate-spin' : ''}`}></i>
                        </button>
                        <button 
                            onClick={handleGenerateSceneVideo}
                            disabled={isAnimatingScene || !!currentSceneVideoUrl}
                            className="bg-slate-950/70 hover:bg-fuchsia-900/60 backdrop-blur-md text-white p-3 rounded-lg border border-slate-600/50 transition-all"
                            title="Animate Scene"
                        >
                            {isAnimatingScene ? <i className="ri-loader-4-line animate-spin text-lg"></i> : <i className="ri-clapperboard-line text-lg"></i>}
                        </button>
                    </div>
                    )}

                    {/* System Group */}
                    <div className="flex gap-1 ml-1 border-l border-slate-700/50 pl-1">
                        <button 
                            onClick={handleEndQuest}
                            className="bg-rose-950/70 hover:bg-rose-900/80 backdrop-blur-md text-rose-300 p-3 rounded-lg border border-rose-600/50 transition-all"
                            title="End Quest & Archive"
                        >
                            <i className="ri-stop-circle-line text-lg"></i>
                        </button>
                    </div>
                 </div>
            </div>

            {/* MIDDLE AREA - Responsive Grid/Flex */}
            {viewMode === 'scene' && renderSceneView()}

            {/* Full Screen Media Overlay */}
            {showFullScreenMedia && (currentSceneVideoUrl || gameState.currentSceneImageUrl) && (
                <div className="fixed inset-0 z-[9999] bg-black/95 backdrop-blur-md flex flex-col items-center justify-center pointer-events-auto animate-fade-in-up">
                    <button 
                        onClick={() => setShowFullScreenMedia(false)} 
                        className="absolute top-4 right-4 text-white hover:text-rose-400 transition-colors z-50"
                        title="Close Full Screen"
                    >
                        <i className="ri-close-circle-line text-4xl"></i>
                    </button>

                    <div className="flex-grow w-full h-full flex items-center justify-center p-4">
                        {currentSceneVideoUrl ? (
                            <video 
                                src={currentSceneVideoUrl} 
                                autoPlay 
                                controls 
                                loop 
                                className="max-w-full max-h-full rounded-lg shadow-2xl border border-indigo-500/30"
                            />
                        ) : (
                            <img 
                                src={gameState.currentSceneImageUrl!} 
                                alt="Full Screen Scene" 
                                className="max-w-full max-h-full object-contain rounded-lg shadow-2xl border border-indigo-500/30"
                            />
                        )}
                    </div>

                    <div className="p-6 w-full flex justify-center bg-gradient-to-t from-black via-black/80 to-transparent absolute bottom-0">
                         <Button 
                            onClick={() => handleDownloadMedia(currentSceneVideoUrl || gameState.currentSceneImageUrl!, `RPGNexus_${currentSceneVideoUrl ? 'Video' : 'Image'}_${Date.now()}.${currentSceneVideoUrl ? 'webm' : 'png'}`)} 
                            className="bg-indigo-600 hover:bg-indigo-500 text-white px-8 py-3 text-lg font-bold shadow-lg shadow-indigo-500/40"
                         >
                            <i className="ri-download-cloud-2-line mr-2"></i> Download Artifact
                        </Button>
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

