                    <i className="ri-send-plane-fill text-xl"></i>
                </button>
            </div>

            {/* Action Buttons List */}
            <div className="flex flex-col gap-2 overflow-y-auto custom-scrollbar-thin pr-1 pb-1 flex-grow lg:flex-grow-0 lg:max-h-full max-h-[150px] md:max-h-[200px]">
                {gameState.availableActions?.map((action, idx) => {
                     const riskBorderClass = getRiskColor(action.risk);
                     let btnBg = "bg-slate-900/80 hover:bg-slate-800/90";
                     let borderColor = "border-slate-600";
                     if(action.risk > 0.6) { borderColor = "border-rose-500/50"; btnBg = "bg-rose-950/70 hover:bg-rose-900/80"; }
                     else if(action.risk > 0.3) { borderColor = "border-amber-500/50"; btnBg = "bg-amber-950/70 hover:bg-amber-900/80"; }
                     else { borderColor = "border-emerald-500/50"; btnBg = "bg-emerald-950/70 hover:bg-emerald-900/80"; }

                     return (
                        <button
                            key={idx}
                            onClick={() => {
                                handleAction(action.label, action.risk);
                            }}
                            disabled={isProcessingTurn}
                            className={`w-full text-left p-3 md:p-4 rounded-lg border ${borderColor} ${btnBg} backdrop-blur-sm transition-all group flex justify-between items-center shrink-0 shadow-lg`}
                        >
                            <span className="text-sm md:text-base font-semibold text-slate-100 group-hover:text-white shadow-black drop-shadow-md">{action.label}</span>
                            <span className={`text-[10px] uppercase opacity-70 font-mono bg-black/30 px-2 py-0.5 rounded`}>{action.type}</span>
                        </button>
                    );
                })}
            </div>
        </div>

        {/* NARRATIVE LOG */}
        <div className="lg:w-2/3 order-1 lg:order-2 pointer-events-auto flex flex-col min-h-0 h-full absolute top-16 right-4 bottom-4 z-20 max-w-md">
             <div 
                 className="bg-slate-950/[0.8] backdrop-blur-md border border-slate-700/50 rounded-lg p-4 overflow-y-auto custom-scrollbar flex-grow shadow-2xl relative"
                 ref={logContainerRef} // Ref attached here for scrollTop control
             >
                {gameState.narrativeHistory.slice(-10).map((entry, i) => ( 
                    <div key={i} className={`mb-3 last:mb-0 text-sm md:text-base leading-relaxed relative pr-8 group/entry drop-shadow-md ${entry.type === 'action' ? 'text-indigo-300 font-bold' : 'text-slate-300 font-cormorant'}`}>
                        {entry.type === 'action' && <span className="mr-2 opacity-50">></span>}
                        {entry.text}
                        <button 
                            onClick={() => playNarrativeAudio(entry.text)}
                            className={`absolute top-0 right-0 text-slate-500 hover:text-emerald-400 p-1 opacity-0 group-hover/entry:opacity-100 transition-opacity ${isPlayingAudio && currentlyPlayingText === entry.text ? 'text-emerald-400 opacity-100 animate-pulse' : ''}`}
                            title="Play Audio"
                            aria-label="Play narrative audio"
                        >
                            <i className={`ri-${isPlayingAudio && currentlyPlayingText === entry.text ? 'volume-up' : 'play-circle'}-line text-lg`}></i>
                        </button>
                    </div>
                ))}

                {isProcessingTurn && (
                    <div className="flex items-center gap-2 text-indigo-400 animate-pulse mt-4 p-2 bg-indigo-900/20 rounded border border-indigo-500/30">
                        <i className="ri-quill-pen-line"></i> 
                        <span className="text-xs font-mono">The Game Master weaves the fate...</span>
                    </div>
                )}

                {/* Audio Status */}
                {isPlayingAudio && (
                     <div className="sticky bottom-0 right-0 ml-auto w-fit mt-2 bg-black/80 backdrop-blur px-3 py-1 rounded-full text-[10px] text-emerald-400 flex items-center gap-2 border border-emerald-500/30 shadow-lg z-10">
                         <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping"></span>
                         Speaking...
                     </div>
                )}
             </div>
        </div>

        {/* Loot Overlay */}
        {foundLoot && (
            <div className="absolute inset-0 z-50 bg-slate-950/95 backdrop-blur-xl flex flex-col p-4 rounded-lg border-2 border-emerald-500 animate-fade-in-up items-center justify-center pointer-events-auto">
                <h3 className="text-2xl font-cinzel font-bold text-emerald-400 mb-2">Relic Recovered!</h3>
                <div className="text-6xl mb-4 text-emerald-200 animate-bounce"><i className={foundLoot.icon}></i></div>
                <div className="text-xl font-bold text-white mb-1">{foundLoot.name}</div>
                <div className="text-sm text-slate-400 mb-4 italic">{foundLoot.description}</div>
                <Button onClick={handleAddToInventory} className="bg-emerald-700 hover:bg-emerald-600 px-6 py-2">
                    Add to Inventory
                </Button>
            </div>
        )}
    </div>
  );

  if (!gameState.currentLocation || gameState.narrativeHistory.length <= 1) {
      return (
          <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans flex flex-col" style={{ width: width || '100%', height: height || '100%' }}>
            {renderInitialization()}
          </div>
      );
  }

  return (
    <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans flex flex-col" style={{ width: width || '100%', height: height || '100%' }}>
        {/* BACKGROUND LAYER - Only visible in Scene Mode */}
        {viewMode === 'scene' && (
            <div className="absolute inset-0 z-0">
                {currentSceneVideoUrl ? (
                    <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
                ) : gameState.currentSceneImageUrl ? (
                    <img src={gameState.currentSceneImageUrl} alt="Scene" className="w-full h-full object-cover transition-opacity duration-1000 ease-in-out" />
                ) : (
                     <div className="w-full h-full bg-slate-900 flex items-center justify-center">
                        <div className="text-slate-700 animate-pulse text-6xl"><i className="ri-image-line"></i></div>
                     </div>
                )}
                {/* VIGNETTE & GRADIENT OVERLAY */}
                <div className="absolute inset-0 bg-gradient-to-b from-slate-950/90 via-slate-950/20 to-slate-950/90 pointer-events-none"></div>
                <div className="absolute inset-0 bg-black/30 pointer-events-none"></div> 
            </div>
        )}

        {/* MAP LAYER - Only visible in Map Mode */}
        {viewMode === 'map' && (
             <div className="absolute inset-0 z-0 bg-slate-900">
                <LoreMapVisualizer 
                    currentLocationId={gameState.currentLocation} 
                    onTravel={(node) => handleTravel(node.id, { description: node.description, genre: node.genre })} 
                    width={1000} // Will scale
                    height={800} // Will scale
                />
             </div>
        )}

        {/* CONTENT LAYER */}
        <div className="relative z-10 flex flex-col h-full p-2 md:p-4 pointer-events-none overflow-hidden"> 

            {/* TOP BAR: Stats & Controls (RESTORED HUD) */}
            <div className="flex flex-wrap justify-between items-start gap-2 mb-2 pointer-events-auto shrink-0">
                 <div className="bg-slate-950/70 backdrop-blur-md border border-slate-700/50 rounded-lg p-3 shadow-lg flex-grow max-w-full md:max-w-md">
                    <h3 className="text-indigo-300 font-bold text-lg font-cinzel flex items-center gap-2 truncate border-b border-white/10 pb-1 mb-1">
                        <i className="ri-map-pin-user-fill"></i> {gameState.currentLocation}
                    </h3>
                    <div className="flex flex-wrap items-center gap-4 text-xs font-mono text-slate-300">
                         <div className="flex items-center gap-1.5" title="Integrity">
                             <i className="ri-heart-pulse-fill text-rose-500"></i> 
                             <div className="w-16 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                                 <div className="h-full bg-rose-600" style={{ width: `${gameState.vitals?.integrity}%` }}></div>
                             </div>
                             {gameState.vitals?.integrity}%
                         </div>
                         <div className="flex items-center gap-1.5" title="Sanity">
                             <i className="ri-brain-fill text-purple-400"></i>
                             <div className="w-16 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                                 <div className="h-full bg-purple-500" style={{ width: `${gameState.vitals?.sanity}%` }}></div>
                             </div>
                             {gameState.vitals?.sanity}%
                         </div>
                         <div className="flex items-center gap-1 ml-auto" title="Flux">
                             <i className="ri-copper-coin-line text-amber-400 text-sm"></i> 
                             <span className="text-amber-200 font-bold">{activeProfile?.flux || 0}</span>
                         </div>
                    </div>
                 </div>

                 {/* VISUAL & AUDIO CONTROLS */}
                 <div className="flex flex-wrap gap-1 shrink-0 justify-end items-start">
                    {/* Navigation Group */}
                    <div className="flex gap-1">
                        <button
                            onClick={() => setViewMode(prev => prev === 'scene' ? 'map' : 'scene')}
                            className={`bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border transition-all ${viewMode === 'map' ? 'border-cyan-500 text-cyan-400' : 'border-slate-600/50 text-slate-400 hover:text-white'}`}
                            title={viewMode === 'scene' ? "Open Star Map" : "Return to Scene"}
                        >
                             <i className={`ri-${viewMode === 'scene' ? 'map-2' : 'landscape'}-line text-lg`}></i>
                        </button>

                        <button 
                            onClick={handleCompileStoryVideo} 
                            disabled={isCompilingStory || !gameState.sceneHistory?.length}
                            className={`bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border transition-all ${isCompilingStory ? 'border-amber-500 text-amber-400 animate-pulse' : 'border-slate-600/50 text-slate-400 hover:text-white'}`}
                            title="Compile Quest Reel (Movie)"
                        >
                            <i className="ri-movie-2-line text-lg"></i>
                        </button>

                        <button 
                            onClick={handleDownloadStory}
                            className="bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border border-slate-600/50 text-slate-400 hover:text-white transition-all"
