                                controls 
                                loop 
                                className="max-w-full max-h-full rounded-lg shadow-2xl border border-indigo-500/30"
                            />
                        ) : (
                            <img 
                                src={gameState.currentSceneImageUrl!} 
                                alt="Full Screen Scene" 
                                className="max-w-full max-h-full object-contain rounded-lg shadow-2xl border border-indigo-500/30"
                            />
                        )}
                    </div>

                    <div className="p-6 w-full flex justify-center bg-gradient-to-t from-black via-black/80 to-transparent absolute bottom-0">
                         <Button 
                            onClick={() => handleDownloadMedia(currentSceneVideoUrl || gameState.currentSceneImageUrl!, `RPGNexus_${currentSceneVideoUrl ? 'Video' : 'Image'}_${Date.now()}.${currentSceneVideoUrl ? 'webm' : 'png'}`)} 
                            className="bg-indigo-600 hover:bg-indigo-500 text-white px-8 py-3 text-lg font-bold shadow-lg shadow-indigo-500/40"
                         >
                            <i className="ri-download-cloud-2-line mr-2"></i> Download Artifact
                        </Button>
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

