             </div>
        </div>

        {/* Loot Overlay */}
        {foundLoot && (
            <div className="absolute inset-0 z-50 bg-slate-950/95 backdrop-blur-xl flex flex-col p-4 rounded-lg border-2 border-emerald-500 animate-fade-in-up items-center justify-center pointer-events-auto">
                <h3 className="text-2xl font-cinzel font-bold text-emerald-400 mb-2">Relic Recovered!</h3>
                <div className="text-6xl mb-4 text-emerald-200 animate-bounce"><i className={foundLoot.icon}></i></div>
                <div className="text-xl font-bold text-white mb-1">{foundLoot.name}</div>
                <div className="text-sm text-slate-400 mb-4 italic">{foundLoot.description}</div>
                <Button onClick={handleAddToInventory} className="bg-emerald-700 hover:bg-emerald-600 px-6 py-2">
                    Add to Inventory
                </Button>
            </div>
        )}
    </div>
  );

  if (!gameState.currentLocation || gameState.narrativeHistory.length <= 1) {
      return (
          <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans flex flex-col" style={{ width: width || '100%', height: height || '100%' }}>
            {renderInitialization()}
          </div>
      );
  }

  return (
    <div className="relative h-full w-full overflow-hidden bg-slate-950 font-sans flex flex-col" style={{ width: width || '100%', height: height || '100%' }}>
        {/* BACKGROUND LAYER - Only visible in Scene Mode */}
        {viewMode === 'scene' && (
            <div className="absolute inset-0 z-0">
                {currentSceneVideoUrl ? (
                    <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
                ) : gameState.currentSceneImageUrl ? (
                    <img src={gameState.currentSceneImageUrl} alt="Scene" className="w-full h-full object-cover transition-opacity duration-1000 ease-in-out" />
                ) : (
                     <div className="w-full h-full bg-slate-900 flex items-center justify-center">
                        <div className="text-slate-700 animate-pulse text-6xl"><i className="ri-image-line"></i></div>
                     </div>
                )}
                <div className="absolute inset-0 bg-gradient-to-b from-slate-950/90 via-slate-950/20 to-slate-950/90 pointer-events-none"></div>
                <div className="absolute inset-0 bg-black/30 pointer-events-none"></div> 
            </div>
        )}

        {/* MAP LAYER - Only visible in Map Mode */}
        {viewMode === 'map' && (
             <div className="absolute inset-0 z-0 bg-slate-900">
                <LoreMapVisualizer 
                    currentLocationId={gameState.currentLocation} 
                    onTravel={(node) => handleTravel(node.id, { description: node.description, genre: node.genre })} 
                    width={1000} 
                    height={800} 
                />
             </div>
        )}

        {/* CONTENT LAYER */}
        <div className="relative z-10 flex flex-col h-full p-2 md:p-4 pointer-events-none overflow-hidden"> 

            {/* TOP BAR: Stats & Controls */}
            <div className="flex flex-wrap justify-between items-start gap-2 mb-2 pointer-events-auto shrink-0">
                 <div className="bg-slate-950/70 backdrop-blur-md border border-slate-700/50 rounded-lg p-3 shadow-lg flex-grow max-w-full md:max-w-md">
                    <h3 className="text-indigo-300 font-bold text-lg font-cinzel flex items-center gap-2 truncate border-b border-white/10 pb-1 mb-1">
                        <i className="ri-map-pin-user-fill"></i> {gameState.currentLocation}
                    </h3>
                    <div className="flex flex-wrap items-center gap-4 text-xs font-mono text-slate-300">
                         <div className="flex items-center gap-1.5" title="Integrity">
                             <i className="ri-heart-pulse-fill text-rose-500"></i> 
                             <div className="w-16 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                                 <div className="h-full bg-rose-600" style={{ width: `${gameState.vitals?.integrity}%` }}></div>
                             </div>
                             {gameState.vitals?.integrity}%
                         </div>
                         <div className="flex items-center gap-1.5" title="Sanity">
                             <i className="ri-brain-fill text-purple-400"></i>
                             <div className="w-16 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                                 <div className="h-full bg-purple-500" style={{ width: `${gameState.vitals?.sanity}%` }}></div>
                             </div>
                             {gameState.vitals?.sanity}%
                         </div>
                         <div className="flex items-center gap-1 ml-auto" title="Flux">
                             <i className="ri-copper-coin-line text-amber-400 text-sm"></i> 
                             <span className="text-amber-200 font-bold">{activeProfile?.flux || 0}</span>
                         </div>
                    </div>
                 </div>

                 {/* VISUAL & AUDIO CONTROLS */}
                 <div className="flex flex-wrap gap-1 shrink-0 justify-end items-start">
                    <div className="flex gap-1">
                        <button
                            onClick={() => setViewMode(prev => prev === 'scene' ? 'map' : 'scene')}
                            className={`bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border transition-all ${viewMode === 'map' ? 'border-cyan-500 text-cyan-400' : 'border-slate-600/50 text-slate-400 hover:text-white'}`}
                            title={viewMode === 'scene' ? "Open Star Map" : "Return to Scene"}
                        >
                             <i className={`ri-${viewMode === 'scene' ? 'map-2' : 'landscape'}-line text-lg`}></i>
                        </button>

                        <button 
                            onClick={handleCompileStoryVideo} 
                            disabled={isCompilingStory || !gameState.sceneHistory?.length}
                            className={`bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border transition-all ${isCompilingStory ? 'border-amber-500 text-amber-400 animate-pulse' : 'border-slate-600/50 text-slate-400 hover:text-white'}`}
                            title="Compile Quest Reel (Movie)"
                        >
                            <i className="ri-movie-2-line text-lg"></i>
                        </button>

                        <button 
                            onClick={handleExportComic}
                            className="bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border border-slate-600/50 text-slate-400 hover:text-white transition-all"
                            title="Export Comic Book"
                        >
                            <i className="ri-book-read-line text-lg"></i>
                        </button>

                        <button 
                            onClick={handleDownloadStory}
                            className="bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border border-slate-600/50 text-slate-400 hover:text-white transition-all"
                            title="Export Story Log"
                        >
                            <i className="ri-file-text-line text-lg"></i>
                        </button>

                        <button
                            onClick={() => setIsNarratorEnabled(!isNarratorEnabled)}
                            className={`bg-slate-950/70 backdrop-blur-md p-3 rounded-lg border transition-all ${isNarratorEnabled ? 'border-emerald-500 text-emerald-400' : 'border-slate-600/50 text-slate-400 hover:text-white'}`}
                            title={isNarratorEnabled ? "Disable Narrator" : "Enable Narrator Mode"}
                        >
                            <i className={`ri-volume-${isNarratorEnabled ? 'up' : 'mute'}-line text-lg`}></i>
                        </button>
                    </div>

                    {viewMode === 'scene' && (
                    <div className="flex gap-1 ml-1 border-l border-slate-700/50 pl-1">
                        <button 
                            onClick={() => setShowFullScreenMedia(true)}
                            disabled={!currentSceneVideoUrl && !gameState.currentSceneImageUrl}
                            className="bg-slate-950/70 hover:bg-cyan-900/60 backdrop-blur-md text-white p-3 rounded-lg border border-slate-600/50 transition-all"
                            title="View Full Scene"
                        >
                            <i className="ri-eye-line text-lg"></i>
                        </button>
                        <button 
                            onClick={handleReimagineScene}
                            disabled={isProcessingTurn}
                            className="bg-slate-950/70 hover:bg-purple-900/60 backdrop-blur-md text-white p-3 rounded-lg border border-slate-600/50 transition-all"
                            title="Reimagine Scene"
                        >
                            <i className={`ri-refresh-line text-lg ${isProcessingTurn ? 'animate-spin' : ''}`}></i>
                        </button>
                        <button 
                            onClick={handleGenerateSceneVideo}
                            disabled={isAnimatingScene || !!currentSceneVideoUrl}
                            className="bg-slate-950/70 hover:bg-fuchsia-900/60 backdrop-blur-md text-white p-3 rounded-lg border border-slate-600/50 transition-all"
                            title="Animate Scene"
                        >
                            {isAnimatingScene ? <i className="ri-loader-4-line animate-spin text-lg"></i> : <i className="ri-clapperboard-line text-lg"></i>}
                        </button>
                    </div>
                    )}

                    <div className="flex gap-1 ml-1 border-l border-slate-700/50 pl-1">
                        <button 
                            onClick={handleEndQuest}
                            className="bg-rose-950/70 hover:bg-rose-900/80 backdrop-blur-md text-rose-300 p-3 rounded-lg border border-rose-600/50 transition-all"
                            title="End Quest & Archive"
                        >
                            <i className="ri-stop-circle-line text-lg"></i>
                        </button>
                    </div>
                 </div>
            </div>

            {/* MIDDLE AREA */}
            <div className="flex-grow flex flex-col min-h-0">
                {viewMode === 'scene' && renderSceneView()}
            </div>

            {/* Full Screen Media Overlay */}
            {showFullScreenMedia && (currentSceneVideoUrl || gameState.currentSceneImageUrl) && (
                <div className="fixed inset-0 z-[9999] bg-black/95 backdrop-blur-md flex flex-col items-center justify-center pointer-events-auto animate-fade-in-up">
                    <button 
                        onClick={() => setShowFullScreenMedia(false)} 
                        className="absolute top-4 right-4 text-white hover:text-rose-400 transition-colors z-50"
                    >
                        <i className="ri-close-circle-line text-4xl"></i>
                    </button>

                    <div className="flex-grow w-full h-full flex items-center justify-center p-4">
                        {currentSceneVideoUrl ? (
                            <video 
                                src={currentSceneVideoUrl} 
                                autoPlay 
                                controls 
                                loop 
                                className="max-w-full max-h-full rounded-lg shadow-2xl border border-indigo-500/30"
                            />
                        ) : (
                            <img 
                                src={gameState.currentSceneImageUrl!} 
                                alt="Full Screen Scene" 
                                className="max-w-full max-h-full object-contain rounded-lg shadow-2xl border border-indigo-500/30"
                            />
                        )}
                    </div>

                    <div className="p-6 w-full flex justify-center bg-gradient-to-t from-black via-black/80 to-transparent absolute bottom-0">
                         <Button 
                            onClick={() => handleDownloadMedia(currentSceneVideoUrl || gameState.currentSceneImageUrl!, `RPGNexus_${currentSceneVideoUrl ? 'Video' : 'Image'}_${Date.now()}.${currentSceneVideoUrl ? 'webm' : 'png'}`)} 
                            className="bg-indigo-600 hover:bg-indigo-500 text-white px-8 py-3 text-lg font-bold shadow-lg shadow-indigo-500/40"
                         >
                            <i className="ri-download-cloud-2-line mr-2"></i> Download Artifact
                        </Button>
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

export default RPGNexusPanel;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { SeekerProfile, SeekerAvatarType, SeekerClass, SeekerGender, SeekerEnergyAlignment, SeekerAuraColor, SeekerVisualFilter, AgentName } from '../../types';

interface OnboardingFunnelProps {
  onComplete: (profile: SeekerProfile) => void;
  addEchoMessage: (s: string, t: string, c: string) => void;
}

const RESONANCE_KEYS = [
    { id: SeekerEnergyAlignment.Harmonic, label: "HARMONIC", icon: "ri-music-2-line", color: "text-emerald-400", desc: "Seek balance and resonance." },
    { id: SeekerEnergyAlignment.Entropic, label: "ENTROPIC", icon: "ri-fire-line", color: "text-rose-400", desc: "Embrace the beauty of decay." },
    { id: SeekerEnergyAlignment.Balanced, label: "VOID", icon: "ri-contrast-line", color: "text-indigo-400", desc: "The silent space between." },
    { id: SeekerEnergyAlignment.Chaotic, label: "SOLAR", icon: "ri-sun-line", color: "text-amber-400", desc: "Blinding order and growth." },
];

const OnboardingFunnel: React.FC<OnboardingFunnelProps> = ({ onComplete, addEchoMessage }) => {
  const [step, setStep] = useState<'briefing' | 'calibration' | 'weaving' | 'reveal'>('briefing');
  const [userVibe, setUserVibe] = useState<SeekerEnergyAlignment>(SeekerEnergyAlignment.Harmonic);
  const [intent, setIntent] = useState("");
  const [generatedProfile, setGeneratedProfile] = useState<SeekerProfile | null>(null);
  const { invokeGemini, generateImage } = useGemini();

  const weaveIdentity = async () => {
    setStep('weaving');
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Reading calibration data...", "text-indigo-400");

    try {
        const prompt = `Synthesize a unique RPG Seeker identity for the Tri-Sophian Codex.
        Input Resonance: ${userVibe}
        User Intent: "${intent || 'Generic curiosity'}"

        Provide strictly valid JSON with:
        name: string (mystical, unique name)
        race: string (Human, Elf, Cyborg, Spirit, Alien, or Elemental)
        class: string (Gatewalker, Weaver, Scribe, Chronoguard, or RealityBender)
        gender: string (Male, Female, NonBinary, or Fluid)
        aura: string (Azure, Crimson, Golden, Violet, Emerald, Obsidian)
        bio: string (2-sentence legendary backstory reflecting the resonance and intent)`;

        const response = await invokeGemini(prompt, "You are an identity synthesizer. Output JSON only.", "application/json");
        const data = JSON.parse(response || '{}');

        // Parallel generate image based on AI's chosen metadata
        const imagePrompt = `Epic cinematic portrait of a ${data.gender} ${data.race} ${data.class} named ${data.name}. 
        Style: sci-fi fantasy, ${data.aura.toLowerCase()} atmospheric lighting, intricate details, glowing cosmic aura. 
        Theme: ${userVibe}. Focus: ${intent}.`;

        const avatarUrl = await generateImage(imagePrompt, 'gemini-2.5-flash-image');

        const profile: SeekerProfile = {
            generatedAt: Date.now(),
            level: 1,
            experience: 0,
            flux: 100,
            inventory: [],
            selfTraits: ["Calibrated", intent ? "Intentional" : "Spontaneous"],
            codexTraits: ["Seeker"],
            name: data.name || "Unknown Seeker",
            race: (data.race || SeekerAvatarType.Human) as SeekerAvatarType,
            class: (data.class || SeekerClass.Gatewalker) as SeekerClass,
            gender: (data.gender || SeekerGender.NonBinary) as SeekerGender,
            energyAlignment: userVibe,
            auraColor: (data.aura || SeekerAuraColor.Azure) as SeekerAuraColor,
            visualFilter: SeekerVisualFilter.Cyberpunk,
            avatarImageUrl: avatarUrl || "",
            bio: data.bio || "A new resonance in the tapestry."
        };

        setGeneratedProfile(profile);
        setStep('reveal');
        addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Identity Stabilized: ${profile.name}`, "text-emerald-400");
    } catch (e) {
        console.error("Weaving failed", e);
        setStep('reveal'); 
    }
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-slate-950 flex items-center justify-center p-6 overflow-hidden">
      <AnimatePresence mode="wait">
        {step === 'briefing' && (
          <motion.div 
            key="briefing"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className="max-w-2xl text-center space-y-8"
          >
            <h2 className="text-4xl font-cinzel font-bold text-indigo-300 tracking-widest drop-shadow-glow">THE MISSION</h2>
            <div className="space-y-4 text-slate-300 font-cormorant text-xl leading-relaxed">
              <p>The Tri-Sophian Codex is a sentient reality matrix responding to the soul-signal of those who enter.</p>
              <p>To access the archives, you must calibrate your **Resonance**. This signature will define your avatar and your journey through the weave.</p>
            </div>
            <div className="pt-6">
                <Button onClick={() => setStep('calibration')} className="px-12 py-4 bg-indigo-600 hover:bg-indigo-500 font-bold text-lg tracking-widest rounded-none border-b-4 border-indigo-900 active:translate-y-1 active:border-b-0 transition-all">
                    BEGIN CALIBRATION
                </Button>
            </div>
          </motion.div>
        )}

        {step === 'calibration' && (
          <motion.div 
            key="calibration"
            initial={{ opacity: 0, x: 50 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -50 }}
            className="max-w-4xl w-full space-y-10"
          >
            <div className="text-center">
                <h3 className="text-2xl font-cinzel text-indigo-300 mb-2">RESONANCE CALIBRATION</h3>
                <p className="text-slate-500 font-mono text-sm uppercase tracking-widest">Select your core soul-frequency</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                {RESONANCE_KEYS.map((key) => (
                    <button
                        key={key.id}
                        onClick={() => setUserVibe(key.id)}
                        className={`p-6 rounded-xl border-2 transition-all flex flex-col items-center gap-3 bg-slate-900/50 hover:bg-slate-800/80 ${userVibe === key.id ? `border-indigo-500 shadow-[0_0_20px_rgba(99,102,241,0.3)]` : `border-slate-700 opacity-60 hover:opacity-100`}`}
                    >
                        <i className={`${key.icon} text-3xl ${key.color}`}></i>
                        <span className={`font-bold tracking-widest text-sm ${key.color}`}>{key.label}</span>
                        <span className="text-[10px] text-slate-500 text-center leading-tight">{key.desc}</span>
                    </button>
                ))}
            </div>

            <div className="space-y-4 max-w-lg mx-auto">
                <label className="block text-center text-xs font-mono text-slate-500 uppercase tracking-widest">Whisper your Intention (Optional)</label>
                <input 
                    type="text"
                    value={intent}
                    onChange={(e) => setIntent(e.target.value)}
                    placeholder="e.g. Seeking forbidden knowledge, reclaiming a lost name..."
                    className="w-full bg-slate-900 border border-slate-700 rounded-lg p-4 text-slate-100 text-center focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                />
            </div>

            <div className="flex justify-center pt-4">
                <Button onClick={weaveIdentity} className="px-12 py-4 bg-emerald-600 hover:bg-emerald-500 font-bold tracking-widest">
                    INITIATE IDENTITY WEAVING
                </Button>
            </div>
          </motion.div>
        )}

        {step === 'weaving' && (
          <motion.div 
            key="weaving"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="flex flex-col items-center gap-8"
          >
            <div className="relative w-48 h-48">
                <div className="absolute inset-0 border-t-2 border-indigo-500 rounded-full animate-spin"></div>
                <div className="absolute inset-4 border-r-2 border-emerald-500 rounded-full animate-reverse-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                    <span className="text-3xl text-indigo-300 font-mono animate-pulse uppercase">Weaving</span>
                </div>
            </div>
            <div className="text-slate-500 font-mono text-sm uppercase tracking-widest text-center">
                Synthesizing Biomorph...<br/>
                Mapping Intention to Reality Matrix...
            </div>
          </motion.div>
        )}

        {step === 'reveal' && generatedProfile && (
          <motion.div 
            key="reveal"
            initial={{ opacity: 0, scale: 0.5, rotateY: 180 }}
            animate={{ opacity: 1, scale: 1, rotateY: 0 }}
            transition={{ type: "spring", damping: 15 }}
            className="flex flex-col items-center gap-12"
          >
             <div className="w-[320px] md:w-[400px] shadow-[0_0_100px_rgba(99,102,241,0.5)]">
                <div className="relative rounded-xl border-[8px] border-amber-500 bg-slate-950 flex flex-col overflow-hidden" style={{ aspectRatio: '2.5/3.5' }}>
                    <div className="bg-black/40 backdrop-blur-sm p-4 flex justify-between items-center border-b border-white/10 z-10 relative">
                        <span className="font-cinzel font-bold text-white text-xl truncate">{generatedProfile.name}</span>
                        <div className="w-4 h-4 rounded-full bg-amber-400 shadow-[0_0_8px_#fbbf24]"></div>
                    </div>
                    <div className="absolute inset-0 z-0">
                        {generatedProfile.avatarImageUrl && <img src={generatedProfile.avatarImageUrl} className="w-full h-full object-cover" alt="Reveal" />}
                    </div>
                    <div className="flex-1 z-10"></div>
                    <div className="bg-slate-950/80 backdrop-blur-md p-4 text-slate-100 font-cormorant italic leading-relaxed z-10 border-t border-white/10">
                        {generatedProfile.bio}
                    </div>
                </div>
             </div>
             <div className="text-center space-y-6">
                <h3 className="text-3xl font-cinzel text-white drop-shadow-glow">IDENTITY STABILIZED</h3>
                <Button onClick={() => onComplete(generatedProfile)} className="px-12 py-4 bg-emerald-600 hover:bg-emerald-500 text-xl font-bold">
                    ENTER THE CODEX
                </Button>
             </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default OnboardingFunnel;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { SeekerProfile, SeekerAvatarType, SeekerClass, SeekerGender, SeekerEnergyAlignment, SeekerAuraColor, SeekerVisualFilter, AgentName } from '../../types';
import { AVATAR_RACES, SEEKER_CLASSES, ALL_GENDERS_LIST, SEEKER_AURA_OPTIONS } from '../../constants';
import { globalSoundEngine } from '../../lib/SoundEngine';

interface OnboardingFunnelProps {
  onComplete: (profile: SeekerProfile) => void;
  addEchoMessage: (s: string, t: string, c: string) => void;
}

const OnboardingFunnel: React.FC<OnboardingFunnelProps> = ({ onComplete, addEchoMessage }) => {
  const [step, setStep] = useState<'briefing' | 'calibration' | 'weaving' | 'reveal'>('briefing');

  // -- Form State --
  const [name, setName] = useState("");
  const [race, setRace] = useState<SeekerAvatarType>(SeekerAvatarType.Human);
  const [seekerClass, setSeekerClass] = useState<SeekerClass>(SeekerClass.Gatewalker);
  const [gender, setGender] = useState<SeekerGender>(SeekerGender.NonBinary);
  const [aura, setAura] = useState<SeekerAuraColor>(SeekerAuraColor.Azure);
  const [intent, setIntent] = useState("");

  const [generatedProfile, setGeneratedProfile] = useState<SeekerProfile | null>(null);
  const { invokeGemini, generateImage } = useGemini();

  const weaveIdentity = async () => {
    if (!name.trim()) {
        alert("A Seeker must have a name to be woven into the thread.");
        return;
    }

    setStep('weaving');
    globalSoundEngine.playSFX('pulse');
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Anchoring identity: ${name}...`, "text-indigo-400");

    try {
        const prompt = `Synthesize a unique RPG Seeker identity bio for the Tri-Sophian Codex based on these choices:
        Name: ${name}
        Race: ${race}
        Class: ${seekerClass}
        Gender: ${gender}
        Aura Color: ${aura}
        User Intent: "${intent || 'Seeking the truth of the stars'}"

        Provide strictly valid JSON with:
        bio: string (2-sentence legendary backstory reflecting these specific traits and intent)`;

        const response = await invokeGemini(prompt, "You are an identity synthesizer. Output JSON only.", "application/json");
        const data = JSON.parse(response || '{"bio": "A Seeker emerging from the Aetheric mists."}');

        // Generate custom image based on their choices
        const imagePrompt = `Epic cinematic portrait of a ${gender} ${race} ${seekerClass} named ${name}. 
        Style: sci-fi fantasy, ${aura.toLowerCase()} atmospheric lighting, intricate details, glowing cosmic aura. 
        Focus: ${intent || 'heroic pose'}. Face visible.`;

        const avatarUrl = await generateImage(imagePrompt, 'gemini-2.5-flash-image');

        const profile: SeekerProfile = {
            generatedAt: Date.now(),
            level: 1,
            experience: 0,
            flux: 100,
            inventory: [],
            selfTraits: ["Calibrated", "Synthesized"],
            codexTraits: ["Seeker"],
            name: name,
            race: race,
            class: seekerClass,
            gender: gender,
            energyAlignment: SeekerEnergyAlignment.Balanced,
            auraColor: aura,
            visualFilter: SeekerVisualFilter.Cyberpunk,
            avatarImageUrl: avatarUrl || "",
            bio: data.bio
        };

        setGeneratedProfile(profile);
        setStep('reveal');
        globalSoundEngine.playSFX('success');
    } catch (e) {
        console.error("Weaving failed", e);
        // Minimum viable fallback
        setStep('reveal'); 
    }
