  const renderSceneView = () => (
    <div className="flex flex-col lg:block h-full w-full relative">
        {/* ACTIONS DECK - Bottom on mobile, Bottom-Left on Desktop */}
        <div className="lg:w-1/3 flex flex-col gap-2 pointer-events-auto min-h-0 shrink-0 relative lg:absolute bottom-4 left-0 lg:left-4 z-20 max-w-full lg:max-w-sm px-2 lg:px-0 mt-auto">
             {/* Custom Input */}
            <div className="flex gap-2 mb-1 bg-slate-950/40 p-2 rounded-lg border border-slate-700/50 backdrop-blur-sm shrink-0">
                <input 
                    type="text" 
                    value={customActionInput}
                    onChange={(e) => setCustomActionInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAction(customActionInput)}
                    placeholder="What do you do?"
                    className="flex-grow bg-transparent border-none text-sm md:text-base text-slate-100 placeholder-slate-500 focus:ring-0 min-w-0"
                    disabled={isProcessingTurn}
                />
                <button 
                    onClick={() => handleAction(customActionInput)}
                    disabled={isProcessingTurn || !customActionInput.trim()}
                    className="text-indigo-400 hover:text-indigo-300 px-2"
                >
                    <i className="ri-send-plane-fill text-xl"></i>
                </button>
            </div>

            {/* Action Buttons List */}
            <div className="flex flex-col gap-2 overflow-y-auto custom-scrollbar-thin pr-1 pb-1 flex-grow lg:flex-grow-0 max-h-[30vh] lg:max-h-full">
                {gameState.availableActions?.map((action, idx) => {
                     let btnBg = "bg-slate-900/60 hover:bg-slate-800/80";
                     let borderColor = "border-slate-600";
                     if(action.risk > 0.6) { borderColor = "border-rose-500/50"; btnBg = "bg-rose-950/50 hover:bg-rose-900/70"; }
                     else if(action.risk > 0.3) { borderColor = "border-amber-500/50"; btnBg = "bg-amber-950/50 hover:bg-amber-900/70"; }
                     else { borderColor = "border-emerald-500/50"; btnBg = "bg-emerald-950/50 hover:bg-emerald-900/70"; }

                     return (
                        <button
                            key={idx}
                            onClick={() => handleAction(action.label, action.risk)}
                            disabled={isProcessingTurn}
                            className={`w-full text-left p-3 md:p-4 rounded-lg border ${borderColor} ${btnBg} backdrop-blur-sm transition-all group flex justify-between items-center shrink-0 shadow-lg`}
                        >
                            <span className="text-sm md:text-base font-semibold text-slate-100 group-hover:text-white shadow-black drop-shadow-md truncate pr-2">{action.label}</span>
                            <div className="flex items-center gap-2 shrink-0">
                                <span className={`text-[9px] uppercase font-bold px-1.5 py-0.5 rounded ${action.risk > 0.6 ? 'bg-rose-600/50 text-rose-200' : action.risk > 0.3 ? 'bg-amber-600/50 text-amber-200' : 'bg-emerald-600/50 text-emerald-200'}`}>
