        </div>

        {/* NARRATIVE LOG - Shared space on mobile, Absolute on Desktop */}
        <div className="lg:w-2/3 pointer-events-auto flex flex-col min-h-0 flex-1 lg:absolute lg:top-16 lg:right-4 lg:bottom-4 z-20 w-full lg:max-w-md px-2 lg:px-0 py-2 lg:py-0">
             <div 
                 className="bg-slate-950/[0.4] backdrop-blur-md border border-slate-700/50 rounded-lg p-4 overflow-y-auto custom-scrollbar flex-grow shadow-2xl relative"
                 ref={logContainerRef}
             >
                {gameState.narrativeHistory.slice(-12).map((entry, i) => ( 
                    <div key={i} className={`mb-3 last:mb-0 text-sm md:text-base leading-relaxed relative pr-8 group/entry drop-shadow-md ${entry.type === 'action' ? 'text-indigo-300 font-bold' : 'text-slate-300 font-cormorant'}`}>
