// --- Random Name Generator ---
const NAME_PREFIXES = ["Xyl", "Chron", "Vor", "Zyn", "Kael", "Thal", "Om", "Lyra", "Vex", "Ser", "Dra", "Myr", "Pyr", "Cyp", "Nek", "Sol", "Zen", "Rin", "Kys", "Tor", "Ael", "Fen", "Grim"];
const NAME_SUFFIXES = ["os", "ia", "ex", "on", "is", "us", "ar", "or", "a", "yn", "ix", "um", "ra", "th", "en", "ir", "ae", "io", "ak", "ul"];

const generateRandomName = () => {
    const prefix = NAME_PREFIXES[Math.floor(Math.random() * NAME_PREFIXES.length)];
    const suffix = NAME_SUFFIXES[Math.floor(Math.random() * NAME_SUFFIXES.length)];
    return prefix + suffix;
};

// Helper function to get icon for card type
const getCardTypeIcon = (type: string): string => {
    switch (type) {
        case 'Creature': return 'ri-aliens-line';
        case 'NPC': return 'ri-user-star-line';
        case 'Boss': return 'ri-skull-2-line';
        case 'Location': return 'ri-map-pin-range-line';
        case 'Weapon': return 'ri-sword-line';
        case 'Companion': return 'ri-bear-smile-line';
        case 'Environment': return 'ri-landscape-line';
        case 'Relic': return 'ri-vip-diamond-line';
        case 'Consumable': return 'ri-flask-line';
        case 'Vehicle': return 'ri-rocket-line';
        case 'Augmentation': return 'ri-cpu-line';
        case 'Skin': return 'ri-t-shirt-line';
        case 'Mount': return 'ri-riding-line';
        case 'Dwelling': return 'ri-home-heart-line';
        case 'Skill': return 'ri-book-open-line';
        case 'Material': return 'ri-stack-line';
        case 'Service': return 'ri-service-line';
        case 'Collectible': return 'ri-trophy-line';
        case 'Fashion': return 'ri-shirt-line';
        case 'Food': return 'ri-restaurant-line';
        case 'Pet': return 'ri-bear-smile-line'; // Reuse
        case 'Music': return 'ri-music-line';
        case 'Tool': return 'ri-hammer-line';
        case 'Planet': return 'ri-earth-line';
        case 'Secret': return 'ri-eye-off-line';
        case 'Element': return 'ri-fire-line';
        case 'Cursed': return 'ri-skull-line';
        case 'Festival': return 'ri-flag-line';
        default: return 'ri-apps-2-line';
    }
}

// TCG Card Component
const TCGCard: React.FC<{ 
    name: string, 
    type: string, 
    rarity: ArtifactRarity, 
    imageUrl?: string, 
    description?: string, 
    stats?: { atk: number, def: number, res: number },
    auraColor?: string,
    id?: string,
    isZoomed?: boolean
}> = ({ name, type, rarity, imageUrl, description, stats, auraColor, id, isZoomed = false }) => {
    const rarityColors = {
        [ArtifactRarity.Common]: 'border-slate-500 bg-slate-900',
        [ArtifactRarity.Uncommon]: 'border-emerald-500 bg-emerald-950',
        [ArtifactRarity.Rare]: 'border-blue-500 bg-blue-950',
        [ArtifactRarity.Legendary]: 'border-amber-500 bg-amber-950',
        [ArtifactRarity.Mythic]: 'border-fuchsia-500 bg-fuchsia-950',
        [ArtifactRarity.Anomalous]: 'border-rose-600 bg-rose-950',
    };

    const borderColor = rarityColors[rarity] || rarityColors[ArtifactRarity.Common];
    const auraHex = auraColor ? SEEKER_AURA_OPTIONS.find(a=>a.id === auraColor)?.hex : 'transparent';

    return (
        <div 
            id={id} 
            className={`relative rounded-xl border-[8px] ${borderColor} flex flex-col overflow-hidden shadow-2xl transition-transform duration-300 ${isZoomed ? 'scale-105' : ''}`}
            style={{ 
                aspectRatio: '2.5/3.5',
                boxShadow: auraColor ? `0 0 30px ${auraHex}60` : 'none'
            }}
        >
            {/* Holographic Overlay */}
            <div className="absolute inset-0 pointer-events-none z-20 bg-gradient-to-tr from-transparent via-white/10 to-transparent opacity-30 mix-blend-overlay" />

            {/* Header - Semi Transparent Glass (High Transparency) */}
            <div className="bg-black/10 backdrop-blur-sm p-4 flex justify-between items-center border-b border-white/10 z-10 relative">
                <span className="font-cinzel font-bold text-white text-lg md:text-xl truncate drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)]">{name}</span>
                <div className="flex gap-1">
                    <div className="w-4 h-4 rounded-full bg-current opacity-90 shadow-[0_0_8px_currentColor]" style={{color: auraHex}}></div>
                </div>
            </div>

            {/* Image Area */}
            <div className="absolute inset-0 z-0 bg-black">
                 {/* Image covers full card background for immersive feel, layout overlays it */}
                {imageUrl ? (
                    <img src={imageUrl} alt={name} className="w-full h-full object-cover" />
                ) : (
                    <div className="w-full h-full flex items-center justify-center text-slate-600">
                        <i className={`${getCardTypeIcon(type)} text-8xl opacity-30`}></i>
                    </div>
                )}
                 {/* Inner Frame */}
                 <div className="absolute inset-3 border border-white/20 rounded-lg opacity-40 pointer-events-none"></div>
            </div>

            {/* Spacer to push content down */}
            <div className="flex-1 z-10"></div>

            {/* Info Bar - Glass */}
            <div className="bg-slate-900/30 backdrop-blur-md p-2 flex justify-between items-center border-t border-b border-white/10 z-10 relative">
                <span className="text-[10px] uppercase tracking-wider text-slate-100 font-bold drop-shadow-md">{type}</span>
                <span className={`text-[9px] uppercase font-bold px-2 py-0.5 rounded shadow-sm ${rarity === 'Legendary' ? 'text-amber-100 bg-amber-900/60 border border-amber-500/30' : 'text-slate-200 bg-slate-800/60'}`}>{rarity}</span>
            </div>

            {/* Text Box - High Transparency Glass */}
            {/* Increased opacity to 70 and removed text-shadow for better html2canvas capture */}
            <div className="h-[28%] bg-slate-950/70 backdrop-blur-md p-4 text-sm text-slate-100 font-cormorant italic leading-snug overflow-hidden relative z-10 border-t border-white/10">
                {description || "No data available."}
            </div>

            {/* Footer Stats */}
            {stats && (
                <div className="bg-black/60 backdrop-blur-md p-2 flex justify-around items-center border-t border-white/10 z-10 relative text-sm font-mono font-bold tracking-wider">
                    <div className="flex items-center text-red-400 drop-shadow-md"><i className="ri-sword-fill mr-1.5"></i>{stats.atk}</div>
                    <div className="flex items-center text-blue-400 drop-shadow-md"><i className="ri-shield-fill mr-1.5"></i>{stats.def}</div>
                    <div className="flex items-center text-purple-400 drop-shadow-md"><i className="ri-flashlight-fill mr-1.5"></i>{stats.res}</div>
                </div>
            )}
        </div>
    );
};

const SeekerProfileWeaverPanel: React.FC<SeekerProfileWeaverPanelProps> = ({
  addEchoMessage,
  onProfileCreated,
  existingProfile,
  onUpdateProfile,
  width,
  height
}) => {
  const [name, setName] = useState(existingProfile?.name || '');
  const [race, setRace] = useState<SeekerAvatarType>(existingProfile?.race || SeekerAvatarType.Human);
  const [seekerClass, setSeekerClass] = useState<SeekerClass>(existingProfile?.class || SeekerClass.Gatewalker);
  const [gender, setGender] = useState<SeekerGender>(existingProfile?.gender || SeekerGender.NonBinary);
  const [alignment, setAlignment] = useState<SeekerEnergyAlignment>(existingProfile?.energyAlignment || SeekerEnergyAlignment.Harmonic);
  const [aura, setAura] = useState<SeekerAuraColor>(existingProfile?.auraColor || SeekerAuraColor.Azure);
  const [visualFilter, setVisualFilter] = useState<SeekerVisualFilter>(existingProfile?.visualFilter || SeekerVisualFilter.Cyberpunk);

  const [avatarUrl, setAvatarUrl] = useState<string | undefined>(existingProfile?.avatarImageUrl);
  const [isGeneratingAvatar, setIsGeneratingAvatar] = useState(false);
  const [isWeavingBio, setIsWeavingBio] = useState(false); // New state for bio generation

  const [activeTab, setActiveTab] = useState<'profile' | 'grimoire'>('profile');

  const { generateImage, invokeGemini } = useGemini();

  // Update local state if existingProfile changes externally
  useEffect(() => {
    if (existingProfile) {
      setName(existingProfile.name);
      setRace(existingProfile.race);
      if (existingProfile.class) setSeekerClass(existingProfile.class);
      setGender(existingProfile.gender);
      setAlignment(existingProfile.energyAlignment);
      if (existingProfile.auraColor) setAura(existingProfile.auraColor);
      if (existingProfile.visualFilter) setVisualFilter(existingProfile.visualFilter);
      if (existingProfile.avatarImageUrl) setAvatarUrl(existingProfile.avatarImageUrl);
    }
  }, [existingProfile]);

  const handleRandomizeProfile = () => {
      setName(generateRandomName());
      setRace(AVATAR_RACES[Math.floor(Math.random() * AVATAR_RACES.length)].id as SeekerAvatarType);
      setSeekerClass(SEEKER_CLASSES[Math.floor(Math.random() * SEEKER_CLASSES.length)].id as SeekerClass);
      setGender(ALL_GENDERS_LIST[Math.floor(Math.random() * ALL_GENDERS_LIST.length)]);
      setAlignment(ALL_ALIGNMENTS_LIST[Math.floor(Math.random() * ALL_ALIGNMENTS_LIST.length)]);
      setAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
      setVisualFilter(SEEKER_VISUAL_FILTERS[Math.floor(Math.random() * SEEKER_VISUAL_FILTERS.length)].id as SeekerVisualFilter);
      addEchoMessage(AgentName.System, "Randomized Identity Parameters.", "text-cyan-300");
  };

  const handleGenerateAvatar = async () => {
      if (isGeneratingAvatar || !name || !race || !seekerClass) {
          if(!name) addEchoMessage(AgentName.System, "Name required for avatar generation.", "text-yellow-400");
          return;
      }

      setIsGeneratingAvatar(true);
      addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Weaving visual avatar...", "text-indigo-300");

      const equipStr = existingProfile 
        ? `Wearing ${existingProfile.equippedOutfit?.name || 'standard gear'}, Wielding ${existingProfile.equippedWeapon?.name || 'basic weapon'}.`
        : '';

      const prompt = `Portrait of a ${gender} ${race} ${seekerClass}, sci-fi fantasy style, detailed, glowing ${aura} aura, ${visualFilter} aesthetic. 
      IMPORTANT: No text, no words, no paragraphs in image. Purely visual portrait. Face visible. ${equipStr}`;

      try {
          const url = await generateImage(prompt, 'gemini-2.5-flash-image');
          if (url) {
              setAvatarUrl(url);
              addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Avatar manifested.", "text-emerald-300");
          } else {
              addEchoMessage(AgentName.System, "Avatar generation failed.", "text-rose-400");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Error generating avatar.", "text-rose-400");
      } finally {
          setIsGeneratingAvatar(false);
      }
  };

  const handleCreateOrUpdate = async () => {
    if (!name.trim()) {
        addEchoMessage(AgentName.System, "Identity requires a name.", "text-rose-400");
        return;
    }

    if (isWeavingBio) return; // Prevent multiple clicks

    const selfTraits = existingProfile?.selfTraits || [
        TRAIT_LISTS.self[Math.floor(Math.random() * TRAIT_LISTS.self.length)],
        TRAIT_LISTS.self[Math.floor(Math.random() * TRAIT_LISTS.self.length)]
    ];

    const codexTraits = existingProfile?.codexTraits || [
        TRAIT_LISTS.codex[Math.floor(Math.random() * TRAIT_LISTS.codex.length)]
    ];

    // Always reweave bio on update/create to match current parameters
    setIsWeavingBio(true);
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Weaving legendary biography...", "text-fuchsia-300");

    let bio = existingProfile?.bio || "";

    try {
        const bioPrompt = `Write a 2-sentence epic, mystical, sci-fi fantasy backstory for a ${gender} ${race} ${seekerClass} named ${name} with ${alignment} alignment. Mention a lost artifact or cosmic event. Tone: Mysterious, Legendary.`;
        const generatedBio = await invokeGemini(bioPrompt, "You are a master storyteller for a cosmic RPG.");
        if (generatedBio) {
            bio = generatedBio;
            addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Biography inscribed.", "text-emerald-300");
        }
    } catch (e) {
        console.warn("Bio generation failed", e);
        addEchoMessage(AgentName.System, "Bio generation failed, retaining previous.", "text-yellow-400");
    }

    // Preserving all existing fields using spread, then overwriting with new form data
    const newProfile: SeekerProfile = {
        ...(existingProfile || {
            generatedAt: Date.now(),
            level: 1,
            experience: 0,
            flux: 100,
            inventory: [],
            selfTraits: [],
            codexTraits: []
        }),
        name,
        race,
        class: seekerClass,
        gender,
        energyAlignment: alignment,
        auraColor: aura,
        visualFilter,
        selfTraits: Array.from(new Set(selfTraits)),
        codexTraits: Array.from(new Set(codexTraits)),
        avatarImageUrl: avatarUrl,
        bio: bio // Add bio to profile
    };

    if (existingProfile && onUpdateProfile) {
        onUpdateProfile(newProfile);
        addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Profile updated for ${name}.`, "text-emerald-300");
    } else if (onProfileCreated) {
        onProfileCreated(newProfile);
        addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Identity woven: ${name} (${race} ${seekerClass}).`, "text-cyan-300");
    }

    setIsWeavingBio(false);
  };

  const handleDownloadCard = () => {
      const cardElement = document.getElementById('seeker-tcg-card');
      if (cardElement) {
          // Add a small delay to ensure rendering is stable and scale up for better resolution
          setTimeout(() => {
              html2canvas(cardElement, {
                  backgroundColor: null,
                  scale: 3, 
                  useCORS: true,
                  allowTaint: true
              }).then(canvas => {
                  const link = document.createElement('a');
                  link.download = `TCG_Card_${name.replace(/\s+/g, '_') || 'Seeker'}.png`;
                  link.href = canvas.toDataURL('image/png');
                  link.click();
                  addEchoMessage(AgentName.SeekerProfileWeaverAgent, "TCG Identity Card materialized.", "text-emerald-300");
              }).catch(err => {
                  console.error("Card capture failed:", err);
                  addEchoMessage(AgentName.System, "Card capture failed.", "text-rose-400");
              });
          }, 100);
      }
  };

  const inventoryGroups = useMemo(() => {
    if (!existingProfile) return {};
    const groups: Record<string, MarketItem[]> = {};
    existingProfile.inventory.forEach(item => {
        const type = item.type; 
        if (!groups[type]) groups[type] = [];
        groups[type].push(item);
    });
    return groups;
  }, [existingProfile]);

  const seekerStats = existingProfile ? {
      atk: Math.floor(existingProfile.level * 10 + (existingProfile.flux / 100)),
      def: Math.floor(existingProfile.level * 8 + (existingProfile.inventory.length * 2)),
      res: Math.floor(existingProfile.level * 12 + 5)
  } : { atk: 10, def: 10, res: 10 };

  return (
    <div 
        className="seeker-profile-weaver-panel bg-slate-950/90 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl flex flex-col my-4 overflow-hidden" 
        style={{ width: width ? (typeof width === 'number' ? `${width}px` : width) : '100%', height: height ? (typeof height === 'number' ? `${height}px` : height) : '500px' }}
    >
      <div className="p-4 border-b border-indigo-800/50 bg-slate-900/50 flex justify-between items-center shrink-0">
        <h3 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center">
            <i className="ri-user-6-line mr-2"></i>Seeker Identity Loom
        </h3>
        {existingProfile && (
            <div className="flex gap-2">
                <button 
                    onClick={() => setActiveTab('profile')}
                    className={`px-3 py-1 rounded text-xs font-bold transition-colors ${activeTab === 'profile' ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-400 hover:text-white'}`}
                >
                    Profile
                </button>
                 <button 
                    onClick={() => setActiveTab('grimoire')}
                    className={`px-3 py-1 rounded text-xs font-bold transition-colors ${activeTab === 'grimoire' ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-400 hover:text-white'}`}
                >
                    Grimoire ({existingProfile.inventory.length})
                </button>
            </div>
        )}
      </div>

      <div className="flex-grow overflow-hidden flex flex-col relative">
        {activeTab === 'profile' && (
            <div className="p-6 overflow-y-auto custom-scrollbar space-y-6">

                {/* TCG CARD DISPLAY AREA */}
                <div className="flex flex-col xl:flex-row gap-8 items-center xl:items-start">
                    {/* The Rendered Card - Made Larger */}
                    <div className="w-full max-w-sm md:w-[420px] flex-shrink-0 relative group mx-auto xl:mx-0">
                         <TCGCard 
                            id="seeker-tcg-card"
                            name={name || "Unknown Seeker"}
                            type={`${race} ${seekerClass}`}
                            rarity={ArtifactRarity.Legendary}
                            imageUrl={avatarUrl}
                            description={existingProfile?.bio || `A ${alignment} ${race} wandering the Codex. ${existingProfile?.selfTraits.join(', ') || ''}`}
                            stats={seekerStats}
                            auraColor={aura}
                            isZoomed
                         />

                         <div className="mt-6 flex flex-col gap-3">
                            <div className="flex gap-2">
                                 <Button onClick={handleCreateOrUpdate} disabled={isWeavingBio} className="flex-grow py-2 bg-gradient-to-r from-indigo-700 to-purple-700 hover:from-indigo-600 hover:to-purple-600 shadow-lg font-cinzel font-bold text-xs tracking-wide rounded-lg border border-indigo-500/30">
                                    {isWeavingBio ? <><i className="ri-loader-4-line animate-spin mr-2"></i>Weaving...</> : (existingProfile ? 'UPDATE IDENTITY' : 'WEAVE IDENTITY')}
                                </Button>
                                 <Button onClick={handleGenerateAvatar} disabled={isGeneratingAvatar} className="flex-grow text-xs py-2 bg-indigo-700 hover:bg-indigo-600 shadow-lg">
                                    {isGeneratingAvatar ? <i className="ri-loader-4-line animate-spin"></i> : <><i className="ri-magic-line mr-2"></i>Generate Art</>} 
                                </Button>
                            </div>
                             <Button onClick={handleDownloadCard} disabled={!avatarUrl} className="w-full text-xs py-2 bg-slate-700 hover:bg-slate-600 shadow-lg">
                                <i className="ri-download-line mr-2"></i> Save Card
                            </Button>
                         </div>
                    </div>

                    {/* Editor Form */}
                    <div className="flex-grow w-full space-y-5 bg-slate-900/50 p-6 rounded-xl border border-slate-700/50">
                        <div className="grid grid-cols-1 gap-5">
                             <div className="space-y-1.5">
                                <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Designation (Name)</label>
                                <div className="flex gap-2">
                                    <input 
                                        type="text" 
                                        value={name} 
                                        onChange={e => setName(e.target.value)} 
                                        className="flex-grow bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all placeholder-slate-500"
                                        placeholder="Enter Seeker Name..."
                                    />
                                    <button 
                                        onClick={handleRandomizeProfile}
                                        className="px-4 bg-slate-800 border border-slate-600 rounded-lg hover:bg-indigo-900/50 hover:border-indigo-500 text-indigo-400 hover:text-indigo-200 transition-all shadow-sm group"
                                        title="Randomize Complete Identity"
                                    >
                                        <i className="ri-dice-fill text-xl group-hover:animate-spin-slow"></i>
                                    </button>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Biomorph (Race)</label>
                                    <select 
                                        value={race} 
                                        onChange={e => setRace(e.target.value as SeekerAvatarType)}
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                                    >
                                        {AVATAR_RACES.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Archetype (Class)</label>
                                     <select 
                                        value={seekerClass} 
                                        onChange={e => setSeekerClass(e.target.value as SeekerClass)}
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                                    >
                                        {SEEKER_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                    </select>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Gender</label>
                                     <select 
                                        value={gender} 
                                        onChange={e => setGender(e.target.value as SeekerGender)}
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                                    >
                                        {ALL_GENDERS_LIST.map(g => <option key={g} value={g}>{g}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Alignment</label>
                                     <select 
                                        value={alignment} 
                                        onChange={e => setAlignment(e.target.value as SeekerEnergyAlignment)}
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                                    >
                                        {ALL_ALIGNMENTS_LIST.map(a => <option key={a} value={a}>{a}</option>)}
                                    </select>
                                </div>
                            </div>

                             <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Reality Filter</label>
                                     <select 
                                        value={visualFilter} 
                                        onChange={e => setVisualFilter(e.target.value as SeekerVisualFilter)}
                                        className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                                    >
                                        {SEEKER_VISUAL_FILTERS.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider mb-1">Aura Signature</label>
                                    <div className="grid grid-cols-4 sm:grid-cols-8 gap-3 p-3 bg-slate-800 border border-slate-600 rounded-lg">
                                        {SEEKER_AURA_OPTIONS.map(option => (
                                            <button
                                                key={option.id}
                                                onClick={() => setAura(option.id)}
                                                className={`w-7 h-7 rounded-full border-2 transition-all duration-200 focus:outline-none ${
                                                    aura === option.id 
                                                    ? 'border-white scale-125 ring-2 ring-indigo-400 ring-offset-2 ring-offset-slate-900 shadow-lg' 
                                                    : 'border-transparent hover:scale-110 opacity-70 hover:opacity-100'
                                                }`}
                                                style={{ backgroundColor: option.hex, boxShadow: `0 0 10px ${option.hex}` }}
                                                title={option.name}
                                                aria-label={`Select ${option.name} aura`}
                                                aria-pressed={aura === option.id}
                                            />
                                        ))}
                                    </div>
                                    <div className="text-center text-[10px] text-indigo-200 mt-1 uppercase tracking-wide font-bold">{SEEKER_AURA_OPTIONS.find(a => a.id === aura)?.name}</div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* ... (Grimoire tab remains same) ... */}
        {activeTab === 'grimoire' && existingProfile && (
            <div className="flex-1 overflow-y-auto p-6 bg-[url('https://www.transparenttextures.com/patterns/dark-leather.png')] bg-slate-900 custom-scrollbar">
                <h2 className="text-center font-cinzel text-2xl text-amber-200 mb-6 drop-shadow-md">Grimoire of Collected Cards</h2>

                {Object.entries(inventoryGroups).map(([group, items]: [string, MarketItem[]]) => (
                    <div key={group} className="mb-8">
                        <h3 className="text-lg font-cinzel font-bold text-slate-400 border-b border-slate-700 mb-4 pb-1 flex items-center">
                            <i className={`${getCardTypeIcon(group)} mr-2 opacity-50`}></i>{group}
                        </h3>
                        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                            {items.map((item, idx) => (
                                <div key={`${item.id}-${idx}`} className="transform hover:scale-105 transition-transform duration-200 cursor-pointer">
                                     <TCGCard 
                                        name={item.name}
                                        type={item.type}
                                        rarity={item.rarity}
                                        description={item.description}
                                     />
                                     {/* Quick Equip for Inventory View */}
                                     {['Weapon', 'Companion', 'Relic', 'Fashion'].includes(item.type) && (
                                         <button 
                                            className="w-full mt-1 bg-slate-800 hover:bg-indigo-600 text-white text-[9px] py-1 rounded border border-slate-600 hover:border-indigo-400 transition-colors"
                                            onClick={() => {
                                                const newProfile = {...existingProfile};
                                                if(item.type === 'Weapon') newProfile.equippedWeapon = item;
                                                if(item.type === 'Companion') newProfile.equippedCompanion = item;
                                                if(item.type === 'Relic') newProfile.equippedRelic = item;
                                                if(item.type === 'Fashion') newProfile.equippedOutfit = item;
                                                onUpdateProfile(newProfile);
                                                addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Equipped ${item.name}`, 'text-emerald-400');
                                            }}
                                         >Equip</button>
                                     )}
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
                {existingProfile.inventory.length === 0 && (
                    <div className="flex flex-col items-center justify-center h-64 text-slate-600 opacity-50">
                        <i className="ri-book-open-line text-6xl mb-4"></i>
                        <p>The Grimoire awaits your discoveries.</p>
                    </div>
                )}
            </div>
        )}
      </div>
    </div>
  );
};

