interface GenesisMovement {
    id: string;
    title: string;
    description: string;
    icon: string;
    prompt: string;
}

const MOVEMENTS: GenesisMovement[] = [
    { 
        id: 'A', 
        title: 'Non-Commutative Geometric Consciousness', 
        description: 'Transcend Hilbert space into automorphic forms of relation.',
        icon: 'ri-shape-line',
