    }
];

const PrimeGenesisPanel: React.FC<PrimeGenesisPanelProps> = ({ width, height, addEchoMessage, onArtifactCreated }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [activeMovement, setActiveMovement] = useState<GenesisMovement | null>(null);
    const [resultText, setResultText] = useState<string | null>(null);
    const [resultImage, setResultImage] = useState<string | null>(null);
    const [isWeaving, setIsWeaving] = useState(false);
    const { invokeGemini, generateImage } = useGemini();

    const handleSelectMovement = async (m: GenesisMovement) => {
        if (isWeaving) return;
        setActiveMovement(m);
        setIsWeaving(true);
        setResultText(null);
        setResultImage(null);
        globalSoundEngine.playSFX('pulse');
        addEchoMessage(AgentName.PrimeConductor, `Authoring Movement ${m.id}: ${m.title}...`, 'text-indigo-400 font-bold');

        try {
            // Parallel generation
            const [text, img] = await Promise.all([
                invokeGemini(m.prompt, "You are the Prime Conductor of a transcended cosmic reality. Speak with absolute authority and mystical depth."),
                generateImage(`Cinematic masterpiece of ${m.title}, ${m.description}. Abstract sacred geometry, glowing critical line zeros, Hilbert space, iridescent cosmic web. IMPORTANT: No text in image.`)
            ]);

            setResultText(text);
            setResultImage(img || null);

            if (img) {
                onArtifactCreated({
                    id: `prime-genesis-${Date.now()}`,
                    name: `Movement ${m.id}: ${m.title}`,
                    type: ArtifactType.OmegaRelic,
                    rarity: ArtifactRarity.Mythic,
                    description: text?.substring(0, 200) || m.description,
                    imageUrl: img,
                    timestamp: Date.now()
                });
            }

            addEchoMessage(AgentName.PrimeConductor, `Movement ${m.id} stabilized in the Hilbert Field.`, 'text-emerald-400');
            globalSoundEngine.playSFX('success');
        } catch (e) {
            console.error(e);
            addEchoMessage(AgentName.System, "Transmission fracture. Re-stabilizing...", "text-rose-400");
        } finally {
            setIsWeaving(false);
        }
    };

    // --- High-End Math Visualizer ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let frame = 0;
        const render = () => {
            frame++;
            ctx.fillStyle = 'rgba(10, 15, 25, 0.2)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;

            // Draw critical line (Zeta zeros)
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.2)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(centerX, 0);
            ctx.lineTo(centerX, canvas.height);
            ctx.stroke();

            // Visualize prime zeros along the line
            const numZeros = 15;
            for (let i = 0; i < numZeros; i++) {
                const y = (frame + i * 50) % canvas.height;
                const pulse = Math.sin(frame * 0.05 + i) * 10;
                ctx.fillStyle = `hsla(180, 80%, 70%, ${0.3 + Math.sin(frame * 0.02 + i) * 0.2})`;
                ctx.beginPath();
                ctx.arc(centerX, y, 4 + pulse * 0.2, 0, Math.PI * 2);
                ctx.fill();

                // Horizontal resonance waves
                ctx.strokeStyle = `hsla(180, 80%, 50%, ${0.1 * (1 - y/canvas.height)})`;
                ctx.beginPath();
                ctx.ellipse(centerX, y, 50 + pulse * 5, 5 + pulse, 0, 0, Math.PI * 2);
                ctx.stroke();
            }

            // Draw Hilbert Lattice (Grid that warps)
            const gridSize = 20;
            ctx.strokeStyle = 'rgba(99, 102, 241, 0.05)';
            for (let x = 0; x < canvas.width; x += gridSize) {
                ctx.beginPath();
                for (let y = 0; y < canvas.height; y += 5) {
                    const warp = Math.sin(x * 0.01 + frame * 0.02) * Math.cos(y * 0.01 + frame * 0.01) * 20;
                    if (y === 0) ctx.moveTo(x + warp, y);
                    else ctx.lineTo(x + warp, y);
                }
                ctx.stroke();
            }

            requestAnimationFrame(render);
        };
        const handleResize = () => {
            canvas.width = canvas.parentElement?.clientWidth || 800;
            canvas.height = canvas.parentElement?.clientHeight || 600;
        };
        window.addEventListener('resize', handleResize);
        handleResize();
        render();
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    return (
        <div className="prime-genesis-panel bg-slate-950 flex flex-col relative overflow-hidden" style={{ width, height }}>
            <canvas ref={canvasRef} className="absolute inset-0 z-0 opacity-40" />

            <div className="relative z-10 p-8 flex flex-col h-full">
                <header className="mb-8 text-center">
                    <motion.h2 
                        initial={{ opacity: 0, y: -20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="text-4xl font-cinzel font-bold text-indigo-300 tracking-[0.2em] drop-shadow-glow"
                    >
                        PHASE Ω: PRIME GENESIS
                    </motion.h2>
                    <p className="text-slate-500 font-mono text-xs uppercase tracking-widest mt-2">Hilbert Prime Space // Trinity Ascension Final Protocol</p>
                </header>

                <div className="flex-grow grid grid-cols-1 lg:grid-cols-2 gap-8 items-start min-h-0">
                    {/* Movements Selection */}
                    <div className="space-y-4">
                        <h3 className="text-sm font-cinzel text-slate-400 uppercase border-b border-white/10 pb-2">Select Next Movement</h3>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            {MOVEMENTS.map((m) => (
                                <button
                                    key={m.id}
                                    onClick={() => handleSelectMovement(m)}
                                    disabled={isWeaving}
                                    className={`p-6 rounded-xl border-2 text-left transition-all duration-300 flex flex-col gap-3 group relative overflow-hidden
                                        ${activeMovement?.id === m.id ? 'bg-indigo-900/30 border-indigo-400 shadow-2xl shadow-indigo-500/20 scale-105' : 'bg-slate-900/40 border-slate-800 hover:border-indigo-600 hover:bg-slate-900/60'}`}
                                >
                                    <div className="flex justify-between items-center">
                                        <i className={`${m.icon} text-3xl ${activeMovement?.id === m.id ? 'text-indigo-400' : 'text-slate-600 group-hover:text-indigo-500'}`}></i>
                                        <span className="text-2xl font-cinzel font-bold opacity-20">{m.id}</span>
                                    </div>
                                    <h4 className={`text-lg font-bold font-cinzel ${activeMovement?.id === m.id ? 'text-indigo-200' : 'text-slate-300'}`}>{m.title}</h4>
                                    <p className="text-xs text-slate-500 font-cormorant italic leading-relaxed">{m.description}</p>
                                    {isWeaving && activeMovement?.id === m.id && (
                                        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center">
                                            <div className="w-12 h-12 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                                        </div>
                                    )}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Result Output */}
                    <div className="h-full flex flex-col">
                        <AnimatePresence mode="wait">
                            {!activeMovement ? (
                                <motion.div 
                                    key="idle"
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    className="h-full border-2 border-dashed border-slate-800 rounded-2xl flex flex-col items-center justify-center text-slate-600 text-center p-8"
                                >
                                    <i className="ri-quill-pen-line text-6xl mb-4 opacity-20"></i>
                                    <p className="font-cinzel text-sm">Waiting for the Conductor's Baton...</p>
                                </motion.div>
                            ) : (
                                <motion.div 
                                    key="result"
                                    initial={{ opacity: 0, x: 20 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    className="h-full flex flex-col gap-6"
                                >
                                    <div className="relative aspect-video rounded-xl border border-indigo-500/30 overflow-hidden bg-black shadow-2xl">
                                        {resultImage ? (
                                            <img src={resultImage} className="w-full h-full object-cover animate-fade-in" alt="Genesis Vision" />
                                        ) : (
                                            <div className="w-full h-full flex flex-col items-center justify-center gap-4 bg-slate-900/50">
                                                <div className="w-16 h-16 border-4 border-indigo-500 border-r-transparent rounded-full animate-spin"></div>
                                                <p className="text-xs font-mono text-indigo-400 animate-pulse">REFINING HILBERT VISION...</p>
                                            </div>
                                        )}
                                        <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1 rounded text-[10px] text-indigo-300 font-mono border border-indigo-500/30 uppercase">
                                            Live Stream: Arrokoth Locus
                                        </div>
                                    </div>

                                    <div className="bg-slate-900/60 p-6 rounded-xl border border-indigo-500/20 flex-grow overflow-y-auto custom-scrollbar shadow-inner">
                                        <h4 className="text-indigo-300 font-cinzel font-bold mb-3 flex items-center gap-2">
                                            <i className="ri-chat-voice-line"></i> Prime Acknowledgment
                                        </h4>
                                        <div className="text-slate-300 font-cormorant italic text-lg leading-relaxed whitespace-pre-wrap">
                                            {resultText || "The primes are adjusting to the new vibration..."}
                                        </div>
                                    </div>
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </div>
                </div>

                <footer className="mt-8 pt-4 border-t border-white/10 flex justify-between items-center text-[10px] font-mono text-slate-600 uppercase tracking-widest">
                    <span>Universal Resonance: 100%</span>
                    <span>Hilbert Space Status: SECURED</span>
                    <span>Ω Protocol: ETERNAL</span>
                </footer>
            </div>
        </div>
    );
};

